// THROWAWAY V14: A+B workbench with explicit team, card and song selection drafts.
// All scores, durations and rewards are UI fixtures, not game calculations.
// No account, localStorage, network calls or production mutations are used.
const variants = {D:'A＋B · 融合工作台'};
const taskNames = {home:'游戏工具',team:'配队推荐',score:'估分与选曲',event:'活动收益',ranking:'歌曲排行榜'};
import {members,supports,songs,growthIcons} from './fixture-catalog.mjs';
import {cardSkills} from './fixture-skills.mjs';
import {tgwRanges} from './fixture-tgw.mjs';
import {songMissions} from './fixture-missions.mjs';
// V5: preserve the selected A+B layout; verify selection panels and controls.
// All formations and numbers are fixtures. No production APIs or persistence.
const fresh = () => ({variant:'D',panelOpen:true,task:'team',view:'single',eventView:'quick',region:'global-hmt',pool:'reference',fixed:'reference',owned:false,current:null,song:null,difficulty:'expert',objective:'average',mode:'ordinary',performance:'perfect',growth:'actual',trainingLimit:'2',trial:'none',locks:[],maxLevel:'40',rankingDifficulty:'expert',rankingSort:'grade',sort:'grade',basis:'average',badgeBonus:100,pointBonus:100,rank:'A',boost:'1',budget:100,phase:'cycle',eventGoal:'badges',startingCP:0,bonuses:{instruments:[0,0,0,0,0],ranks:[1,1,1,1,1],tgw:1},precision:{perfect:100,life:100,assist:false,places:[1,1,1]},eventContext:{name:'MyGO!!!!! · 示例活动',band:'MyGO!!!!!',attribute:'红赤',challengeSong:songs[0].id,challengeTeam:'reference'},result:{},status:'idle',error:'',selected:0,savedQuick:null,events:[]});
let s=fresh(), runTimer, toastTimer, editDraft, editorSlot=0, editorKind='member';
let teamDraftId='reference', teamQuery='', songDraft, cardPreview=0, editorOrigin='', selectContext, fieldSequence=0;
const freshCardFilters=()=>({query:'',attribute:'all',band:'all',skill:'all',gekisou:'all',rarity:'all',order:'default'});
let cardFilters=freshCardFilters(),cardSkillsOpen=false;
const main=document.querySelector('#main');
const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const fmt=x=>Number(x).toLocaleString('zh-CN');
const song=()=>songs.find(x=>x.id===s.song);
const key=()=>s.task==='score'?`score-${s.view}`:s.task==='event'?`event-${s.eventView}`:s.task;
const result=()=>s.result[key()];
const source=()=>s.task==='score'?(s.fixed==='current'?s.current?.source:s.fixed):s.pool;
const needsTeam=()=>s.task==='score'||s.task==='event'&&s.eventView==='plan';
const needsSong=()=>s.task==='score'&&s.view==='single'||s.task==='team'&&s.objective!=='power';
const btn=(label,action,cls='secondary',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
function log(action){s.events.push(action);s.events=s.events.slice(-12);}
function notify(message){
 document.querySelector('#live-status').textContent=message;
 const t=document.querySelector('#toast');if(t.matches(':popover-open'))t.hidePopover();
 ([...document.querySelectorAll('dialog[open]')].at(-1)||document.body).append(t);
 t.innerHTML=`<span class="toast-mark" aria-hidden="true">✓</span><span>${esc(message)}</span>${btn('×','dismiss-toast','toast-dismiss','aria-label="关闭提示"')}`;
 t.showPopover();clearTimeout(toastTimer);toastTimer=setTimeout(hideToast,3200);
}
function hideToast(){const t=document.querySelector('#toast');if(t.matches(':popover-open'))t.hidePopover();if(t.parentElement!==document.body)document.body.append(t);}
function sync(){const q=new URL(location.href);q.searchParams.set('variant',s.variant);q.searchParams.set('task',s.task);q.searchParams.delete('view');if(s.task==='score')q.searchParams.set('view',s.view);if(s.task==='event')q.searchParams.set('view',s.eventView);history.replaceState(null,'',q);}
function readURL(){const q=new URLSearchParams(location.search);s.variant='D';if(q.get('variant') in variants)s.variant=q.get('variant');if(q.get('task') in taskNames)s.task=q.get('task');if(['single','songs'].includes(q.get('view')))s.view=q.get('view');if(['quick','plan'].includes(q.get('view')))s.eventView=q.get('view');if(q.get('view')==='baseline')s.task='ranking';}
function cancel(){clearTimeout(runTimer);if(s.status==='running'){s.status='idle';notify('计算已停止，条件已保留。');log('cancel');}}
function change(k,v){cancel();s[k]=v;if(k==='performance'&&v!=='custom')s.precision={...s.precision,perfect:{perfect:100,steady:97,practice:90}[v],life:v==='practice'?70:100,assist:false};s.error='';s.status='idle';if(!['sort','basis','view','eventView','rankingDifficulty','rankingSort'].includes(k))for(const r of Object.values(s.result))r.stale=true;log(`${k}: ${v}`);sync();}
function nav(task){cancel();s.task=task;s.error='';s.status='idle';sync();render();window.scrollTo({top:0});log(`navigate ${task}`);}
function segment(k,rows,label){return `<div class="segments" role="group" aria-label="${label}">${rows.map(([v,l])=>`<button data-set="${k}" data-value="${v}" aria-pressed="${s[k]===v}">${l}</button>`).join('')}</div>`;}
function field(k,label,rows){return `<div class="field choice-field"><span>${label}</span>${segment(k,rows,label)}</div>`;}
function num(k,label,min=0){const values=k==='budget'?[50,100,300]:k==='startingCP'?[0,100,500]:[0,100,200];const step=k==='startingCP'?100:k==='budget'?10:10;return `<div class="field number-field"><span id="num-${k}-${++fieldSequence}">${label}</span><div class="number-stepper">${btn('−','step-number','',`data-key="${k}" data-step="-${step}" data-min="${min}" aria-label="减少${label}"`)}<input data-bind="${k}" type="number" min="${min}" max="100000" value="${s[k]}" inputmode="numeric" aria-label="${label}">${btn('＋','step-number','',`data-key="${k}" data-step="${step}" data-min="${min}" aria-label="增加${label}"`)}</div><div class="number-presets">${values.map(v=>btn(String(v),'preset-number','',`data-key="${k}" data-value="${v}" aria-label="${label}设为${v}" aria-pressed="${Number(s[k])===v}"`)).join('')}</div></div>`;}
function group(title,content,extra=''){return `<section class="input-group"><header><h2>${title}</h2>${extra}</header>${content}</section>`;}
const defaultSlots=()=>[0,1,2,3,4].map(i=>({member:i,support:i}));
const fixtureTeam=(label,src=source()||'reference',leader=2)=>({label,source:src,slots:defaultSlots(),leader,growth:(s.task==='team'||s.task==='event')&&src==='owned'?s.growth:'actual',trial:(s.task==='team'||s.task==='event')&&src==='owned'?s.trial:'none'});
function sourceLabel(t){return t?.trial&&t.trial!=='none'?(t.growth==='train'?'培养＋试用假设':'试用假设'):t?.growth==='train'?'培养假设':t?.source==='reference'?'满养成参考':'实际养成示例';}
function roster(t,editable=false){return `<div class="pair-roster rich-roster" aria-label="五组成员与留影">${t.slots.map((p,i)=>`<button class="roster-pair rich-pair" data-action="${editable?'edit-slot':'inspect-pair'}" data-slot="${i}" style="--card-color:${members[p.member].color}" aria-label="位置${i+1}：${members[p.member].name}与${supports[p.support].support}${t.leader===i?'，队长':''}">${richPair(t,p,i)}</button>`).join('')}</div>${leaderSummary(t)}`;}
function fixedTeam(){return s.fixed==='current'?s.current:s.fixed==='owned'?savedTeams()[1]:savedTeams()[0];}
function compactRoster(t){return `<div class="chosen-roster rich-roster" aria-label="已选择队伍的五组配对">${t.slots.map((p,i)=>`<article class="rich-pair" style="--card-color:${members[p.member].color}">${richPair(t,p,i)}</article>`).join('')}</div>${leaderSummary(t)}<p class="roster-growth-note">${t.source==='reference'?'满养成参考':t.growth==='train'?'培养目标示例':'当前养成示例'} · 等级、Rank、觉醒、演出／激奏技能均为演示进度</p>`;}
function currentBar(){const t=s.task==='score'?fixedTeam():s.current;const title=s.task==='score'?'用于估分的队伍':'对照队伍';return `<section class="selected-team-panel"><header><div><span class="current-icon">${icon('team')}</span><span><small>${title}</small><strong>${t?esc(t.label):'尚未选择'}</strong></span>${t?`<span class="source-chip">${sourceLabel(t)}</span>`:''}</div><div class="team-panel-actions">${t?btn('编辑配对','open-editor','quiet'):''}${btn(t?'更换队伍':'选择队伍','open-team-picker','secondary')}</div></header>${t?missionSummary()+compactRoster(t):`<p>${s.task==='team'?'可以选择一支队伍用于固定配对和对照。推荐候选仍需单独应用。':'可选一支队伍作为对照；活动规划会搜索新的编成。'}</p>`}</section>`;}
function songInput(){return `<button class="song-compact" data-action="open-song"><span class="song-cover">♪</span><span><strong>${song()?esc(song().name):'选择歌曲与难度'}</strong><small>${song()?`${s.difficulty.toUpperCase()} · Lv.${songLevel(song(),s.difficulty)}`:'选定后仅显示谱面摘要'}</small></span><b>${song()?'更换':'选择'} →</b></button>${missionSummary()}`;}
function poolInput(){return group('卡片与养成',segment('pool',[['owned','我的卡库'],['reference','全部卡牌参考']],'推荐卡片范围')+`<p class="input-hint">${s.pool==='reference'?'满养成参考；不会记入你的卡库。':s.owned?'示例卡库：公开目录，养成进度为演示值。':'尚未导入卡库。可载入示例体验。'}</p>${s.pool==='owned'&&!s.owned?btn('载入示例卡库','load-sample','secondary'):''}${s.pool==='owned'&&s.owned?`<div class="fields">${field('growth','这次采用的养成',[['actual','保持实际养成'],['train','允许培养后比较']])}</div>${s.growth==='train'?`<div class="fields">${field('trainingLimit','最多培养几张卡',[['1','1 张'],['2','2 张'],['3','3 张']])}</div>`:''}<details class="advanced"><summary>临时试用未拥有卡牌</summary>${field('trial','临时加入推荐范围',[['none','不加入'],['tomori','高松灯 · 示例新卡'],['anon','千早爱音 · 示例新卡']])}<p>仅本次假设，不修改持有与养成。</p></details>`:''}${bonusEntry()}`,btn('管理卡库','open-library','quiet'));}
function locksInput(){return `<details class="advanced"><summary>固定成员与留影配对${s.locks.length?` · ${s.locks.length} 组已固定`:''}</summary><p>从当前队伍选择必须保留的配对；其余位置继续参与推荐。</p>${s.current?`<div class="lock-list">${s.current.slots.map((slot,i)=>`<label><input type="checkbox" data-lock="${i}" ${s.locks.includes(i)?'checked':''}>${members[slot.member].short}＋${supports[slot.support].support}</label>`).join('')}</div>`:btn('先选择或编辑当前队伍','open-editor','quiet')}</details>`;}
function fixedInput(){const t=fixedTeam();return group('固定队伍',`<button class="team-input-trigger" data-action="open-team-picker">${icon('team')}<span><strong>${t?esc(t.label):'选择用于估分的队伍'}</strong><small>${t?sourceLabel(t):'从参考、示例或当前队伍中选择'}</small></span><b>更换 ›</b></button><p class="input-hint">五组配对已在页面上展示。这里只计算这支队伍。</p>${bonusEntry()}`);}
function playInput(){return `<div class="fields two-fields">${field('mode','演出模式',[['ordinary','普通自由演出'],['gekisou','激奏演出']])}${field('performance','发挥假设',[['perfect','全 Perfect'],['steady','参考发挥'],['practice','练习发挥']])}</div><div class="detail-entry"><button data-action="open-performance"><span>精细发挥</span><small>${precisionSummary(s.precision)}</small><b>›</b></button></div>`;}
function inputs(){
 if(s.task==='team')return group('推荐目标',segment('objective',[['average','平均分'],['minimum','最低分'],['maximum','最高分'],['power','综合力']],'推荐目标')+`<p class="input-hint">${s.objective==='power'?'综合力推荐无需歌曲。':s.objective==='minimum'?'比较技能顺序中的较低估分；不代表实打达档概率。':s.objective==='maximum'?'比较技能顺序中的较高估分。':'按歌曲平均估分推荐成员、留影与队长。'}</p>`)+poolInput()+(needsSong()?group('演出与发挥',playInput()):'')+group('编成限制',locksInput(),'<span class="optional-tag">可选</span>');
 if(s.task==='score')return fixedInput()+(s.view==='single'?group('演出与发挥',playInput()):group('歌曲范围',`<div class="fields two-fields">${field('difficulty','谱面难度',[['expert','EXPERT'],['hard','HARD'],['normal','NORMAL']])}${field('maxLevel','等级上限',[['25','Lv.25'],['27','Lv.27'],['40','不限']])}</div><p class="input-hint">按 AP、满生命、无辅助估分。分数依据与排序在结果区调整。</p>`));
 if(s.eventView==='quick')return group('游戏里显示的加成',`<div class="fields two-fields">${num('badgeBonus','道具加成（%）')}${num('pointBonus','活动 pt 加成（%）')}${field('rank','稳定评分',[['A','A'],['S','S'],['SS','SS']])}${field('boost','每次耗火',[['0','0 火'],['1','1 火'],['3','3 火'],['5','5 火']])}</div><p class="input-hint">两项加成分别影响对应奖励；挑战 pt 单列。</p>`);
 return poolInput()+group('刷取目标与预算',`<div class="fields two-fields">${field('eventGoal','优先目标',[['badges','徽章'],['points','活动 pt'],['both','分别比较']])}${num('budget','总耗火预算',1)}${field('phase','计算范围',[['cycle','普通＋后续挑战'],['direct','仅普通演出']])}${field('maxLevel','稳定完成等级',[['25','Lv.25'],['27','Lv.27'],['40','不限']])}</div><details class="advanced"><summary>已有挑战 pt 与每次消耗</summary><div class="fields two-fields">${num('startingCP','已有挑战 pt')}${field('boost','普通演出每次耗火',[['1','1 火'],['3','3 火'],['5','5 火']])}</div></details>${eventEntry()}`);
}
function missing(){if(s.task==='event'&&s.eventView==='quick'||s.task==='ranking')return '';if(s.task==='score'&&s.fixed==='current'&&!s.current)return '先选择一支用于估分的队伍。';if((s.task==='score'&&s.fixed==='owned'||s.task!=='score'&&s.pool==='owned')&&!s.owned)return '卡库为空，载入示例或改用参考范围。';if(needsSong()&&!song())return '请选择歌曲与难度。';if(s.task==='event'&&s.budget<1)return '总耗火预算应大于 0。';return '';}
function runLabel(){return s.task==='team'?'推荐配队':s.task==='score'?(s.view==='single'?'估算单曲分数':'计算队伍选曲'):'生成刷取方案';}
function toolbar(){const instant=s.task==='event'&&s.eventView==='quick';return `<div class="compute-toolbar"><div><strong>${instant?'调整条件，收益即时更新':s.status==='running'?'正在比较示例方案…':result()?.stale?'条件已修改，请重新计算':result()?'本次结果已生成':'准备好后开始计算'}</strong><small>${instant?'无需队伍与歌曲':missing()||'结果与当前队伍分开保存'}</small></div>${s.variant==='B'?btn('调整计算条件','open-conditions','secondary'):''}${instant?'':btn(s.status==='running'?'停止计算':runLabel(),s.status==='running'?'cancel':'run','primary')}</div>${s.error?`<p class="field-error" role="alert">${s.error}</p>`:''}`;}
function stale(r){return r?.stale?'<p class="stale-notice" role="status">条件已修改，以下是上次计算的快照。重新计算后才能应用。</p>':'';}
function applyButton(label,action,r){return btn(label,action,'primary',r.stale?'disabled title="请重新计算"':'');}
function quick(){const mult=Math.max(1,Number(s.boost));return {badges:Math.floor(({A:300,S:450,SS:600}[s.rank])*(1+s.badgeBonus/100)*mult),points:Math.floor(({A:250,S:375,SS:500}[s.rank])*(1+s.pointBonus/100)*mult),cp:({A:30,S:40,SS:50}[s.rank])*mult};}
function quickResult(){const r=quick();const comparable=s.savedQuick&&s.savedQuick.boost===s.boost;return `<section class="result-card"><header><div><small>普通演出 · 样例奖励</small><h2>${s.rank} 评分 · ${s.boost} 火</h2></div><span class="source-chip">即时更新</span></header><div class="reward-grid"><div><span>每次徽章</span><strong>${fmt(r.badges)}</strong></div><div><span>每次活动 pt</span><strong>${fmt(r.points)}</strong></div><div><span>每次挑战 pt</span><strong>${fmt(r.cp)}</strong></div><div><span>徽章／火</span><strong>${Number(s.boost)?fmt(r.badges/Number(s.boost)):'—'}</strong></div></div>${btn('记住当前方案','remember','secondary')}${s.savedQuick?`<div class="comparison-note">上次 ${fmt(s.savedQuick.badges)} 徽章 · ${comparable?`现在 ${fmt(r.badges-s.savedQuick.badges)} 徽章变化。`:'耗火不同，请在相同消耗下比较。'}<br>活动 pt：${fmt(s.savedQuick.points)} → ${fmt(r.points)}</div>`:''}<div class="result-footer">需要计算队伍和后续挑战？${btn('转入完整规划','to-plan','quiet')}</div></section>`;}
function songRows(isRanking=false){const r=result();const level=isRanking?'40':r?.maxLevel||s.maxLevel;const difficulty=isRanking?s.rankingDifficulty:r?.difficulty||s.difficulty;let rows=songs.map(x=>({...x,level:songLevel(x,difficulty)})).filter(x=>x.level<=Number(level)).map((x,i)=>({...x,score:(isRanking?760000:1080000)-i*3500+(isRanking?0:s.basis==='minimum'?-90000:s.basis==='maximum'?80000:0)}));rows.sort((isRanking?s.rankingSort:s.sort)==='short'?(a,b)=>a.time-b.time:(a,b)=>b.score-a.score);return `<div class="song-table"><div class="song-table-head"><span>歌曲 / 谱面</span><span>时长</span><span>${isRanking?'基准':'档位'}</span><span>估分</span><span></span></div>${rows.map((x,i)=>`<article><div class="song-row-title"><span class="song-order">${String(i+1).padStart(2,'0')}</span><span><h3>${x.name}</h3><small><b class="difficulty-tag">${difficulty.toUpperCase()}</b> Lv.${x.level} · ${x.band}</small></span></div><span class="song-duration">${Math.floor(x.time/60)}:${String(x.time%60).padStart(2,'0')}</span><span class="grade-pill ${x.score>=1000000?'is-ss':''}">${isRanking?'统一':x.score>=1000000?'SS':'S'}</span><strong class="song-score">${fmt(x.score)}</strong>${btn(isRanking?'配队 ↗':'单曲 ↗','use-song','quiet',`data-song="${x.id}" ${!isRanking&&r?.stale?'disabled title="请重新计算"':''} aria-label="${isRanking?'配这首歌':'查看单曲'}：${x.name}"`)}</article>`).join('')}</div>`;}
function resultPanel(){
 if(s.task==='event'&&s.eventView==='quick')return quickResult();
 const r=result();if(s.status==='running')return '<section class="result-card result-placeholder" role="status"><h2>正在比较示例方案…</h2><p>可以停止；输入不会清空。</p></section>';
 if(!r)return `<section class="result-card result-placeholder"><div class="placeholder-pairs">${[0,1,2,3,4].map(i=>`<span>${i===2?'队长':'成员'}<small>留影</small></span>`).join('')}</div><h2>${s.task==='team'?'推荐编成与比较会出现在这里':s.task==='score'?'这支队伍的估分会出现在这里':'预算内收益与两阶段编成会出现在这里'}</h2><p>${missing()||'选好条件，再开始计算。'}</p><small>每份结果保留计算条件，应用前可继续比较。</small></section>`;
 if(s.task==='team'){const t=r.candidates[s.selected]||r.candidates[0];return `${stale(r)}<section class="result-card team-result"><header><div><small>推荐结果 · ${r.objective==='power'?'综合力':'歌曲估分'}</small><h2>${t.label}</h2><span class="source-chip">${sourceLabel(t)}</span></div><div class="score-summary"><strong>${fmt(t.score)}</strong><span>${r.objective==='power'?'综合力':r.objective==='minimum'?'最低分示例':r.objective==='maximum'?'最高分示例':'平均分示例'}</span>${r.objective!=='power'?`<small>范围 ${fmt(t.score-90000)}–${fmt(t.score+80000)}</small>`:''}</div></header><div class="candidate-tabs" role="group" aria-label="比较推荐方案">${r.candidates.map((c,i)=>btn(c.label,'candidate','quiet',`data-index="${i}" aria-pressed="${s.selected===i}"`)).join('')}</div>${roster(t)}<dl class="result-spec"><div><dt>谱面</dt><dd>${r.objective==='power'?'无需歌曲':`${r.songName} · ${r.difficulty.toUpperCase()}`}</dd></div><div><dt>养成假设</dt><dd>${sourceLabel(t)}${t.growth==='train'?` · 最多培养 ${r.trainingLimit} 张`:''}${t.trial!=='none'?' · 临时试用卡':''}</dd></div></dl><div class="result-actions">${applyButton('应用此编成','apply',r)}${btn('用此编成选曲','to-songs','secondary',r.stale?'disabled':'')}${btn('对照当前队伍','compare','quiet')}${btn('技能发动模拟','open-simulation','quiet')}</div>${reasonPreview(t,r)}</section>`;}
 if(s.task==='score'&&s.view==='songs')return `${stale(r)}<section class="result-card"><header><div><small>固定队伍 · AP</small><h2>这支队伍适合的歌曲</h2></div><span class="source-chip">${sourceLabel(r.team)}</span></header><div class="fields two-fields result-filters">${field('basis','判档依据',[['average','平均分'],['minimum','最低分'],['maximum','最高分']])}${field('sort','排列顺序',[['grade','档位优先'],['short','短歌优先'],['score','估分优先']])}</div>${songRows()}<p class="fine-print">两项结果筛选使用已算数据，不重新计算。全 Perfect 假设保持可见。</p></section>`;
 if(s.task==='score')return `${stale(r)}<section class="result-card"><header><div><small>单曲估分 · 样例</small><h2>${r.songName}</h2></div><span class="source-chip">${sourceLabel(r.team)}</span></header><div class="score-summary"><strong>1,080,000</strong><span>平均分 · SS</span><small>最低 990,000　最高 1,160,000</small></div><p class="input-hint">${r.performance==='perfect'?'全 Perfect':r.performance==='steady'?'参考发挥':r.performance==='custom'?'自定义发挥':'练习发挥'} · ${r.mode==='ordinary'?'普通自由演出':'激奏名次 '+r.precision.places.join('/')} · ${r.difficulty.toUpperCase()}</p><div class="skill-track"><span>0:00</span><div>${[0,1,2,3,4].map(i=>`<i style="--segment:${i}"></i>`).join('')}</div><span>结束</span></div><div class="result-actions">${btn('这支队伍选曲','to-songs','primary',r.stale?'disabled':'')}${btn('带入活动规划','to-event','secondary',r.stale?'disabled':'')}</div><div class="result-detail-links">${btn('技能发动模拟','open-simulation','secondary')}${btn('计分明细','open-breakdown','quiet')}</div></section>`;
 return `${stale(r)}<section class="result-card"><header><div><small>${r.budget} 火预算 · 样例方案</small><h2>先看总收益，再看怎么刷</h2></div><span class="source-chip">${sourceLabel(r.team)}</span></header><div class="reward-grid"><div><span>预算内徽章</span><strong>${fmt(r.budget*1240)}</strong></div><div><span>预算内活动 pt</span><strong>${fmt(r.budget*1060)}</strong></div></div><div class="stage-card"><h3>普通演出</h3><p>迷星叫 · EXPERT · SS 示例</p>${roster(r.team)}</div>${r.phase==='cycle'?'<div class="stage-card"><h3>后续挑战 · 独立编成</h3><p>'+esc(songs.find(x=>x.id===r.eventContext.challengeSong)?.name)+' · 专用队伍独立确认。</p><strong>已有 '+fmt(r.startingCP)+' pt · 剩余示例 60 pt</strong>'+roster(savedTeams().find(t=>t.id===r.eventContext.challengeTeam)||savedTeams()[0])+'</div>':''}<div class="result-actions">${applyButton('应用普通编成','apply',r)}${btn('查看阶段规划','open-plan-detail','secondary')}</div></section>`;
}
function tabs(){if(s.task==='score')return `<div class="task-subtabs">${segment('view',[['single','单曲估分'],['songs','队伍选曲']],'估分任务')}</div>`;if(s.task==='event')return `<div class="task-subtabs">${segment('eventView',[['quick','已有加成速算'],['plan','卡库完整规划']],'活动任务')}</div>`;return '';}
function summary(){return `<div class="condition-summary" aria-label="完整条件摘要">${conditionItems().map(x=>`<span class="condition-tag" data-title="${esc(x.title)}" data-copy="${esc(x.copy)}" aria-label="${esc(x.title)}：${esc(x.label)}，悬浮查看说明">${esc(x.label)}</span>`).join('')}</div>`;}
function icon(kind){const paths={team:'<rect x="3" y="5" width="7" height="14" rx="2"/><rect x="14" y="5" width="7" height="14" rx="2"/><path d="M10 12h4"/>',score:'<path d="M4 18V9m5 9V5m5 13v-7m5 7V3"/>',event:'<path d="m13 2-8 12h6l-1 8 9-13h-6z"/>',sliders:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]||paths.sliders}</svg>`;}
function heading(){const copy={team:'成员、留影与队长，一起找到合适的编成。',score:'固定一支队伍，看分数，也看适合的歌。',event:'从单次奖励到预算规划，分别算清每项收益。'};return `<header class="workbench-title"><div><small>游戏工具</small><h1>${taskNames[s.task]}</h1><p>${copy[s.task]}</p></div><nav class="local-nav" aria-label="任务切换">${['team','score','event'].map(t=>`<button data-task="${t}" aria-current="${s.task===t?'page':'false'}">${icon(t)}${taskNames[t]}</button>`).join('')}</nav></header>`;}
function railSummary(){return `<div class="rail-content">${icon('sliders')}<strong>计算条件</strong><span>${s.task==='team'?{average:'平均分',minimum:'最低分',maximum:'最高分',power:'综合力'}[s.objective]:s.task==='score'?s.view==='single'?'单曲':'选曲':'收益'}</span><span>${source()==='reference'?'参考':'卡库'}</span>${needsSong()?`<span class="rail-song">${song()?.name||'未选歌'}</span>`:''}${btn('展开条件','toggle-conditions','rail-expand','aria-label="展开条件"')}</div>`;}
function renderWorkspace(){const shared=`${heading()}${tabs()}${s.task==='event'&&s.eventView==='quick'?'':currentBar()}${needsSong()?songWorkspace():''}`;return `${shared}<div class="hybrid-shell ${s.panelOpen?'':'is-collapsed'}"><aside class="hybrid-conditions"><div class="condition-expanded"><header class="panel-title"><div>${icon('sliders')}<h2>计算条件</h2></div>${btn('‹','toggle-conditions','collapse-button','aria-label="收起条件" title="收起条件"')}</header><div class="condition-scroll">${inputs()}</div><div class="condition-foot">${s.task==='event'&&s.eventView==='quick'?'修改加成，收益即时更新':'修改条件后，重新计算'}</div></div>${railSummary()}<div class="mobile-condition-bar"><div>${summary()}</div>${btn(`${icon('sliders')}调整条件`,'open-conditions','secondary','aria-label="调整计算条件"')}</div></aside><section class="workbench-output">${toolbar()}<div class="active-query">${summary()}</div><div id="result-area">${resultPanel()}</div></section></div>`;}
function home(){return `<header class="workbench-title"><div><small>OTONOTE / TOOLBOX</small><h1>游戏工具</h1></div></header><div class="tool-home-list">${[['team','配队推荐','在卡库中寻找编成，可固定配对、比较培养与试用。'],['score','估分与选曲','固定一支队伍，算单曲分数或比较歌曲档位。'],['event','活动收益','已有加成速算，或规划队伍、歌曲与预算。'],['ranking','歌曲排行榜','独立工具：统一基准的歌曲得分、效率与达档综合力。']].map(([t,label,copy])=>`<button data-task="${t}"><strong>${label}</strong><span>${copy}</span><b>→</b></button>`).join('')}</div><p class="home-secondary">抽卡记录　／　Live2D 预览　／　谱面播放　／　剧情阅读</p>`;}
function ranking(){return `<header class="workbench-title"><div><small>游戏工具 / 独立排行榜</small><h1>歌曲排行榜</h1></div>${btn('返回工具目录','go-home','quiet')}</header><p class="ranking-scope">统一基准条件，不读取个人队伍。正式版继续使用现有排行榜页面。</p><section class="result-card"><div class="fields two-fields">${field('rankingDifficulty','谱面难度',[['expert','EXPERT'],['hard','HARD']])}${field('rankingSort','排行依据',[['grade','得分'],['short','时长']])}</div>${songRows(true)}</section>`;}
function restoreFocus(binding){if(binding){const input=document.querySelector(`dialog[open] [data-bind="${binding}"]`)||main.querySelector(`[data-bind="${binding}"]`);input?.focus({preventScroll:true});}}
function render(){closeSkillHelp();closeConditionHelp();closeSelect();fieldSequence=0;const disclosures=[...document.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent.split('·')[0].trim());const binding=document.activeElement?.dataset?.bind;const conditionScroll=main.querySelector('.condition-scroll')?.scrollTop||0;main.className=`prototype-main workbench-v2 workbench-v3 layout-${s.variant}`;main.innerHTML=s.task==='home'?home():s.task==='ranking'?ranking():renderWorkspace();document.querySelector('#variant-label').textContent=`${s.variant} · ${variants[s.variant]}`;document.querySelector('#tool-navigation').innerHTML=['team','score','event','ranking'].map(t=>`<button data-task="${t}" aria-current="${s.task===t?'page':'false'}">${taskNames[t]}</button>`).join('');document.querySelector('#breadcrumb').innerHTML=`首页概览 <span>/</span> <button data-task="home">游戏工具</button> <span>/</span> <strong>${taskNames[s.task]}</strong>`;document.querySelector('.server-control').innerHTML=`${s.region==='jp'?'日服':'港澳台'}<small>简体中文⌄</small>`;if(document.querySelector('#conditions').open)renderConditions();document.querySelectorAll('details').forEach(d=>{if(disclosures.includes(d.querySelector('summary')?.textContent.split('·')[0].trim()))d.open=true;});restoreFocus(binding);const scroll=main.querySelector('.condition-scroll');if(scroll)scroll.scrollTop=conditionScroll;}
function run(){const error=missing();if(error){s.error=error;render();if(s.variant==='B'||innerWidth<900||!s.panelOpen)openConditions();const target=error.includes('歌曲')?(document.querySelector('dialog[open] [data-action="open-song"]')||document.querySelector('[data-action="open-song"]')):(document.querySelector('dialog[open] [data-action="open-editor"]')||document.querySelector('[data-action="open-editor"]'));target?.focus();notify(error);return;}s.status='running';render();runTimer=setTimeout(()=>{const team=s.task==='score'?structuredClone(fixedTeam()):fixtureTeam('本次编成');const candidates=['推荐方案','另一种配对'].map((label,i)=>demoCandidate(label,i));s.result[key()]={team,candidates,objective:s.objective,source:source(),songName:song()?.name||'未限定',difficulty:s.difficulty,maxLevel:s.maxLevel,mode:s.mode,performance:s.task==='score'&&s.view==='songs'?'perfect':s.performance,growth:s.growth,trainingLimit:s.trainingLimit,trial:s.trial,locks:[...s.locks],budget:s.budget,startingCP:s.startingCP,phase:s.phase,eventGoal:s.eventGoal,boost:s.boost,songId:s.song,bonuses:structuredClone(s.bonuses),precision:s.task==='score'&&s.view==='songs'?{perfect:100,life:100,assist:false,places:[1,1,1]}:structuredClone(s.precision),eventContext:structuredClone(s.eventContext),stale:false};s.status='complete';s.selected=0;document.querySelector('#conditions').close();render();if(innerWidth<950)document.querySelector('#result-area')?.scrollIntoView({block:'start'});log('complete');notify('样例结果已生成，可查看原因或继续比较。');},800);}
function dialogHeader(title,id,copy=''){return `<header class="dialog-heading"><div><h2 id="${id}">${title}</h2>${copy?`<p>${copy}</p>`:''}</div><button class="dialog-close" data-action="close-dialog" aria-label="关闭窗口">×</button></header>`;}
function open(id,html){stopSimulation();document.querySelector('#insight').classList.remove('is-simulation');closeSkillHelp();closeConditionHelp();closeSelect();const d=document.querySelector(`#${id}`);if(html){d.innerHTML=html;if(id==='library')d.classList.remove('is-editor');}if(!d.open)d.showModal();return d;}
function renderConditions(){document.querySelector('#conditions').innerHTML=dialogHeader('计算条件','conditions-title','调整完成后关闭面板，可继续核对结果。')+`<div class="dialog-content">${inputs()}</div>${toolbar()}`;}
function openConditions(){renderConditions();open('conditions');}
function openSong(){songDraft={id:s.song||null,difficulty:s.difficulty,query:'',filters:{attribute:'all',band:'all',level:'all',difficulty:'all'}};renderSongPicker();open('picker');}
function startEditor(team,origin=''){editDraft=structuredClone(team||((s.task==='score'?fixedTeam():s.current)||savedTeams()[0]));editorOrigin=origin;editorSlot=0;editorKind='member';cardPreview=editDraft.slots[0].member;cardFilters=freshCardFilters();cardSkillsOpen=false;editor();}
function library(){open('library',dialogHeader('我的卡库与养成','library-title','持有与实际养成归这里管理；工具只读取。')+`<div class="dialog-content"><h3>${s.owned?'公开卡牌目录示例':'尚未导入示例卡库'}</h3><p>正式版保留账号导入、手动录入和批量养成。</p>${btn('载入示例卡库与队伍','load-sample','primary')}<p class="fine-print">本次不连接真实账号，也不保存数据。</p></div>`);}
function study(){open('study',dialogHeader('验证任务与状态','study-title','A＋B 融合：条件可并排、可收起。排行榜独立。')+`<div class="study-scenarios">${[['new','新用户配队'],['owned','实际养成与试用'],['songs','当前队伍选曲'],['quick','活动加成速算'],['plan','活动完整规划']].map(([v,l])=>btn(l,'scenario','secondary',`data-scenario="${v}"`)).join('')}</div><details class="state-inspector" open><summary>当前样例状态</summary><pre>${esc(JSON.stringify(s,null,2))}</pre></details>`);}
function scenario(v){const variant=s.variant;s=fresh();s.variant=variant;if(v==='owned'||v==='songs'||v==='plan'){s.owned=true;s.pool='owned';s.fixed='current';s.current=fixtureTeam('我的示例队伍','owned');}if(v==='songs'){s.task='score';s.view='songs';}if(v==='quick')s.task='event';if(v==='plan'){s.task='event';s.eventView='plan';}document.querySelector('#study').close();sync();render();window.scrollTo({top:0});}
function sample(){s.owned=true;s.current=fixtureTeam('我的示例队伍','owned');s.pool='owned';s.fixed='current';change('growth','actual');document.querySelector('#library').close();render();notify('示例卡库和队伍已载入，只存在于本次原型。');}
function chosen(){const r=result();return s.task==='team'?r.candidates[s.selected]:r.team;}
function cross(task,view){const r=result();if(!r||r.stale)return;s.current=structuredClone(chosen());s.fixed='current';s.pool=s.current.source;s.view=view||s.view;if(task==='event')s.eventView='plan';nav(task);}
// V4 selectors: in-memory drafts; confirmation is the boundary to workspace state.
function chevron(){return '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg>';}
function selectField(k,label,rows,value,scope){const id=`field-${++fieldSequence}`;const chosen=rows.find(r=>r[0]===value)?.[1]||rows[0]?.[1];return `<div class="field select-widget"><span id="${id}">${label}</span><button class="select-trigger" role="combobox" aria-labelledby="${id}" aria-haspopup="listbox" aria-expanded="false" aria-controls="select-menu" data-action="toggle-options" data-select-key="${k}" data-scope="${scope}" data-value="${value}" data-label="${label}" data-options="${esc(JSON.stringify(rows))}"><span>${chosen}</span>${chevron()}</button></div>`;}
function closeSelect(){const menu=document.querySelector('#select-menu');if(menu?.matches(':popover-open'))menu.hidePopover();selectContext?.trigger?.setAttribute('aria-expanded','false');if(menu&&menu.parentElement!==document.body)document.body.append(menu);selectContext=null;}
function toggleSelect(trigger){if(selectContext?.trigger===trigger){closeSelect();return;}closeSelect();selectContext={key:trigger.dataset.selectKey,scope:trigger.dataset.scope,rows:JSON.parse(trigger.dataset.options),trigger};const menu=document.querySelector('#select-menu');(trigger.closest('dialog')||document.body).append(menu);menu.setAttribute('aria-label',trigger.dataset.label);menu.innerHTML=selectContext.rows.map(([v,l])=>`<button role="option" aria-selected="${v===trigger.dataset.value}" data-action="select-value" data-value="${v}"><span>${l}</span>${v===trigger.dataset.value?'<b>✓</b>':''}</button>`).join('');const rect=trigger.getBoundingClientRect();menu.style.width=`${Math.max(180,rect.width)}px`;menu.style.left=`${Math.min(rect.left,innerWidth-Math.max(180,rect.width)-12)}px`;const height=Math.min(240,selectContext.rows.length*32+8);menu.style.top=`${rect.bottom+height+8>innerHeight?Math.max(12,rect.top-height-6):rect.bottom+6}px`;menu.showPopover();trigger.setAttribute('aria-expanded','true');menu.querySelector('[aria-selected="true"]')?.focus({preventScroll:true});}
function commitSelect(value){const context=selectContext;if(!context)return;const {key,scope}=context;closeSelect();if(scope==='workspace'){change(key,value);render();}else if(scope==='card'){cardFilters[key]=value;editor();}else if(scope==='song'){songDraft.filters[key]=value;renderSongPicker();}const root=document.querySelector('dialog[open]')||main;root.querySelector(`[data-select-key="${key}"][data-scope="${scope}"]`)?.focus({preventScroll:true});}
function savedTeams(){const base=(label,id,source,leader)=>({...fixtureTeam(label,source,leader),id,growth:'actual',trial:'none'});const short=base('MyGO!!!!! · 短歌编成','short','owned',1);short.slots=defaultSlots().map((p,i)=>({...p,support:(i+1)%5}));return [base('满养成参考队伍','reference','reference',2),base('MyGO!!!!! · 练习编成','practice','owned',0),short];}
function teamOptions(){const saved=savedTeams();if(!s.current)return saved;const current={...structuredClone(s.current),id:'current'};return [current,...saved.filter(t=>!(t.label===current.label&&t.source===current.source&&t.leader===current.leader&&JSON.stringify(t.slots)===JSON.stringify(current.slots)))];}
function openTeamPicker(){teamQuery='';teamDraftId=s.task==='score'&&s.fixed==='reference'?'reference':s.current?'current':s.fixed==='owned'?'practice':'reference';renderTeamPicker();open('team-picker');}
function renderTeamPicker(){closeSkillHelp();const focusedTeam=document.activeElement?.dataset.team;const options=teamOptions();const t=options.find(t=>t.id===teamDraftId)||options[0];document.querySelector('#team-picker').innerHTML=dialogHeader('选择队伍','team-picker-title','先核对五组配对和队长，再确认使用。')+`<div class="team-picker-body"><section class="team-list-pane"><label class="search-field">${icon('team')}<input data-team-query type="search" value="${esc(teamQuery)}" placeholder="搜索队伍名称" aria-label="搜索队伍名称"></label><div class="list-caption"><span>当前与示例队伍</span><small>${options.length} 支</small></div><div class="team-option-list">${options.map(x=>`<button class="team-option" data-action="team-choice" data-team="${x.id}" data-team-option data-search="${esc(x.label)}" aria-pressed="${x.id===t.id}" aria-label="选择队伍：${esc(x.label)}"><span class="team-option-icon">${icon('team')}</span><span><strong>${x.label}</strong><small>${x.id==='current'?'当前使用 · ':''}${sourceLabel(x)}</small><span class="team-mini-members">${x.slots.map(p=>`<i style="--card-color:${members[p.member].color}">${members[p.member].short}</i>`).join('')}</span></span>${x.id===t.id?'<b>✓</b>':''}</button>`).join('')}<p class="empty-team-filter empty-filter" hidden>没有匹配的队伍，试试其他名称。</p></div></section><section class="team-preview-pane"><header><div><small>编成预览</small><h3>${t.label}</h3></div><span class="source-chip">${sourceLabel(t)}</span></header>${roster(t)}<dl class="selection-facts"><div><dt>队长</dt><dd>${members[t.slots[t.leader].member].name}</dd></div><div><dt>组成</dt><dd>5 位成员 · 5 张留影</dd></div><div><dt>使用方式</dt><dd>${s.task==='score'?'固定这支队伍进行估分':'作为对照队伍，可继续编辑与固定配对'}</dd></div></dl><p class="selection-note">这里展示样例编成；选择不会改变卡库持有。</p></section></div><footer class="selection-footer"><span>已选 <strong>${t.label}</strong></span><div>${btn('取消','close-dialog','secondary')}${btn('编辑这支队伍','edit-picked-team','secondary')}${btn('使用这支队伍','confirm-team','primary')}</div></footer>`;updateTeamRows();if(focusedTeam)document.querySelector(`#team-picker [data-team="${focusedTeam}"]`)?.focus({preventScroll:true});}
function updateTeamRows(){let count=0;document.querySelectorAll('#team-picker [data-team-option]').forEach(row=>{row.hidden=!row.dataset.search.toLowerCase().includes(teamQuery.toLowerCase());if(!row.hidden)count++;});document.querySelector('#team-picker .empty-team-filter').hidden=count>0;document.querySelector('#team-picker .list-caption small').textContent=`${count} 支`;}
function selectTeam(){const t=teamOptions().find(t=>t.id===teamDraftId);if(!t)return;s.current=structuredClone(t);s.fixed='current';change('locks',[]);document.querySelector('#team-picker').close();render();notify('队伍已选择，五组配对已展示。');}
function songLevel(x,d){return x.levels[d]??x.level;}
function songCard(x,d){return `<div class="selected-song-art"><span>♪</span><small>${x.band}</small></div><div class="song-preview-title"><small>当前选择</small><h3>${x.name}</h3><span>${x.band} · ${Math.floor(x.time/60)}:${String(x.time%60).padStart(2,'0')}</span></div><div class="difficulty-choices" role="group" aria-label="选择谱面难度">${[['normal','NORMAL'],['hard','HARD'],['expert','EXPERT']].map(([v,l])=>btn(`<span>${l}</span><strong>Lv.${songLevel(x,v)}</strong>${v===d?'<b>✓</b>':''}`,'song-difficulty','difficulty-choice',`data-difficulty="${v}" aria-pressed="${v===d}"`)).join('')}</div>`;}
function renderSongPicker(){closeSelect();const d=document.querySelector('#picker');const scroll=d.querySelector('.flat-song-scroll')?.scrollTop||0;const active=document.activeElement?.dataset;const f=songDraft.filters,x=songs.find(x=>x.id===songDraft.id);d.innerHTML=dialogHeader('选择歌曲谱面','picker-title','直接点击谱面难度，确认后使用。')+`<div class="song-filter-sticky">${clearSearch('song',songDraft.query,'搜索曲名或乐队')}${filterChips('song','attribute','颜色',attributeOptions(),f.attribute)}<div class="song-filter-bars">${songBandFilters(f.band)}${filterChips('song','level','等级',[['all','全部'],['under20','≤20'],['20to25','20–25'],['over25','≥25']],f.level)}${filterChips('song','difficulty','难度',[['all','全部'],['easy','EASY'],['normal','NORMAL'],['hard','HARD'],['expert','EXPERT']],f.difficulty)}</div></div><div class="flat-song-scroll"><div class="flat-song-list"></div></div><footer class="selection-footer"><span>${x?`<strong>${x.name}</strong><small>${songDraft.difficulty.toUpperCase()} · Lv.${songLevel(x,songDraft.difficulty)}</small>`:'点击一首歌的谱面难度'}</span><div>${btn('取消','close-dialog','secondary')}${btn('使用此谱面','confirm-song','primary',x?'':'disabled')}</div></footer>`;updateSongRows();d.querySelector('.flat-song-scroll').scrollTop=scroll;if(active?.song)d.querySelector(`[data-action="choose-chart"][data-song="${active.song}"][data-difficulty="${active.difficulty}"]`)?.focus({preventScroll:true});}
function updateSongRows(){const f=songDraft.filters,q=songDraft.query.trim().toLowerCase();let charts=0;const filtered=songs.map(x=>({...x,visibleLevels:['easy','normal','hard','expert'].filter(d=>x.levels[d]!=null).map(d=>[d,x.levels[d]]).filter(([d,l])=>(f.difficulty==='all'||d===f.difficulty)&&matchesSongLevel(l,f.level))})).filter(x=>x.visibleLevels.length&&(f.attribute==='all'||x.attribute===f.attribute)&&(f.band==='all'||x.band===f.band)&&(`${x.name}${x.band}`.toLowerCase().includes(q)));document.querySelector('#picker .flat-song-list').innerHTML=`<div class="filter-count"><span>${filtered.length} 首歌曲</span><button data-action="reset-song-filters" class="quiet">清除筛选</button></div>`+filtered.map(x=>{charts+=x.visibleLevels.length;const c=members.find(m=>m.attr===x.attribute);return `<article class="chart-song"><img class="chart-cover" src="${x.cover}" alt="${x.name}封面" loading="lazy"><div class="chart-song-title"><strong>${x.name}</strong><small>${c?`<img src="${c.attributeIcon}" alt="${x.attribute}">`:''}${x.attribute} · ${x.band}</small></div><div class="chart-options">${x.visibleLevels.map(([diff,level])=>btn(`<span>${diff.toUpperCase()}</span><strong>${level}</strong>${songDraft.id===x.id&&songDraft.difficulty===diff?'<b>✓</b>':''}`,'choose-chart',`chart-button diff-${diff}`,`data-song="${x.id}" data-difficulty="${diff}" aria-label="选择${x.name} ${diff.toUpperCase()} Lv.${level}" aria-pressed="${songDraft.id===x.id&&songDraft.difficulty===diff}"`)).join('')}</div></article>`;}).join('')+(filtered.length?'':'<p class="empty-filter">没有符合条件的谱面。可放宽等级或清除筛选。</p>');}
function cardTitle(i){return (editorKind==='member'?members:supports)[i].card;}
function cardGrid(){const collection=editorKind==='member'?members:supports;let list=collection.map((m,i)=>({...m,i})).filter(x=>(cardFilters.attribute==='all'||x.attr===cardFilters.attribute)&&(cardFilters.band==='all'||x.band===cardFilters.band)&&(cardFilters.rarity==='all'||x.rarity===cardFilters.rarity)&&(cardFilters.skill==='all'||x.skill.split(',').includes(cardFilters.skill))&&(cardFilters.gekisou==='all'||x.gekisou===cardFilters.gekisou)&&(`${x.name}${x.card}${x.band}`.toLowerCase().includes(cardFilters.query.trim().toLowerCase())));if(cardFilters.order==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'));return `<div class="card-choice-grid">${list.map(x=>`<button class="card-choice" data-action="editor-card" data-card="${x.i}" aria-pressed="${cardPreview===x.i}" aria-label="预览${editorKind==='member'?'成员':'留影'}：${x.card}"><span class="real-card-art" ${skillTrigger(editorKind,x.i)}><img src="${x.image}" alt="${x.card}" loading="lazy"><span class="art-band">${bandBadge(x)}</span>${missionMatch(x)}<span class="art-facets"><img src="${x.rarityIcon}" alt="${x.rarity}"><img src="${x.attributeIcon}" alt="${x.attr}"></span></span><span class="card-choice-copy"><strong>${x.card}</strong><small>${x.name} · ${x.band}</small><small>${skillLabel(x.skill)} · ${x.gekisou?skillLabel(x.gekisou):'无激奏'}</small></span>${editDraft.slots[editorSlot][editorKind]===x.i?'<span class="in-use-tag">当前使用</span>':''}${cardPreview===x.i?'<span class="card-check">✓</span>':''}</button>`).join('')||'<p class="empty-filter">没有符合条件的卡片，可清除筛选或放宽条件。</p>'}</div><p class="catalog-count">${list.length} 张卡片 · 公开目录快照，养成为演示值</p>`;}
function updateCardGrid(){closeSkillHelp();document.querySelector('#library .card-grid-holder').innerHTML=cardGrid();}
function editor(){closeSkillHelp();closeSelect();const d=document.querySelector('#library');const scroll=d.querySelector('.card-grid-holder')?.scrollTop||0;const active=document.activeElement?.dataset;const p=editDraft.slots[editorSlot],collection=editorKind==='member'?members:supports,m=collection[cardPreview],current=p[editorKind]===cardPreview;const skillOptions=editorKind==='member'?[['all','全部演出技能'],['simple','得分提升'],['life','LIFE加成'],['judgement','判定辅助']]:[['all','全部支援技能'],['score','得分提升'],['heal','生命恢复'],['judge','判定辅助']];open('library',dialogHeader('编辑队伍与配对','library-title','先选位置，再选卡片；应用后更新整支队伍。')+`<div class="card-editor-body"><aside class="position-pane"><div class="position-pane-title"><strong>五组配对</strong><small>${sourceLabel(editDraft)}</small></div><div class="position-list" aria-label="选择编成位置">${editDraft.slots.map((p,i)=>`<button class="position-option" data-action="edit-slot" data-slot="${i}" aria-pressed="${i===editorSlot}" aria-label="编辑位置 ${i+1}：${members[p.member].name}"><img class="position-card-image" src="${members[p.member].image}" alt=""><span><strong>${members[p.member].name}</strong><small>${supports[p.support].support}</small></span><b>${i===editDraft.leader?'队长':i+1}</b></button>`).join('')}</div>${btn(editDraft.leader===editorSlot?'当前位置已是队长':'将此位置设为队长','editor-leader','secondary',editDraft.leader===editorSlot?'disabled':'')}</aside><section class="card-browser-pane"><div class="card-filter-sticky"><div class="card-search-line">${clearSearch('card',cardFilters.query,'搜索卡名或角色')}<div class="segments" role="group" aria-label="卡牌类型">${['member','support'].map(k=>btn(k==='member'?'成员卡':'留影','editor-kind','quiet',`data-kind="${k}" aria-pressed="${editorKind===k}"`)).join('')}</div></div><div class="card-common-filters">${filterChips('card','attribute','颜色',attributeOptions(),cardFilters.attribute)}${selectField('band','乐队',bandOptions(collection),cardFilters.band,'card')}</div><div class="card-rarity-line">${filterChips('card','rarity','稀有度',[['all','全部'],...['R','SR','SSR','EX','BD'].filter(r=>collection.some(x=>x.rarity===r)).map(r=>[r,r])],cardFilters.rarity)}${btn('清除','reset-card-filters','quiet', 'aria-label="清除全部卡片筛选"')}</div><details class="card-skill-filters" ${cardSkillsOpen?'open':''}><summary>技能筛选${cardFilters.skill!=='all'||cardFilters.gekisou!=='all'?`<b>${[cardFilters.skill!=='all'?skillLabel(cardFilters.skill):'',cardFilters.gekisou!=='all'?skillLabel(cardFilters.gekisou):''].filter(Boolean).join(' · ')}</b>`:'<small>演出 / 激奏</small>'}<span>⌄</span></summary><div class="facet-selects">${selectField('skill',editorKind==='member'?'演出技能':'支援技能',skillOptions,cardFilters.skill,'card')}${selectField('gekisou','激奏技能',[['all','全部激奏'],['combo','COMBO'],['just','JUST'],['luck','LUCK']],cardFilters.gekisou,'card')}</div></details></div><div class="card-grid-holder">${cardGrid()}</div></section><aside class="card-preview-pane"><span class="preview-art-frame" ${skillTrigger(editorKind,cardPreview,editDraft)}><img class="real-preview-image" src="${m.image}" alt="${m.card}">${growthOverlay(editDraft,editorKind,cardPreview)}</span><small class="preview-eyebrow">${editorKind==='member'?'成员卡':'留影'}预览 · ${m.rarity} · ${m.attr}</small><h3>${m.card}</h3><p class="preview-character">${m.name} · ${m.band}</p><p class="preview-skill">${skillLabel(m.skill)} · ${skillLabel(m.gekisou)}</p>${btn(current?'当前位置已使用':'替换此位置','put-card','secondary',current?'disabled':'')}<p class="selection-note">养成为示例进度；替换只改变草稿。</p></aside></div><footer class="selection-footer editor-footer"><span>队长 <strong>${members[editDraft.slots[editDraft.leader].member].name}</strong><small>应用前不改变页面队伍</small></span><div>${btn('取消修改','discard-edit','secondary')}${btn('应用编辑后的队伍','save-edit','primary')}</div></footer>`).classList.add('is-editor');d.querySelector('.card-grid-holder').scrollTop=scroll;if(active?.action){const selectors=['card','slot','kind','key','value'].filter(k=>active[k]!==undefined).map(k=>`[data-${k}="${active[k]}"]`).join('');d.querySelector(`[data-action="${active.action}"]${selectors}`)?.focus({preventScroll:true});}}
function growthValues(t,kind,index){const card=(kind==='member'?members:supports)[index];const maximum=t.source==='reference'||t.growth==='train';return kind==='member'?{level:maximum?(card.rarity==='SSR'?90:card.rarity==='SR'?80:70):60+index%3*5,rank:maximum?5:2+index%3,awake:maximum?4:1+index%3,live:maximum?5:2+index%4,gekisou:maximum?5:1+index%5}:{level:maximum?(card.rarity==='SSR'?90:card.rarity==='SR'?80:70):45+index%4*5,rank:maximum?5:1+index%5};}
function growthRow(t,kind,index){const v=growthValues(t,kind,index);const stats=kind==='member'?[[growthIcons.memberLevel,`等级 Lv.${v.level}`,`Lv.${v.level}`],[growthIcons.rank,`Rank ${v.rank}/5`,`${v.rank}/5`],[growthIcons.awake,`觉醒 ${v.awake}/4`,`${v.awake}/4`],['',`演出技能 Lv.${v.live}/5`,`演 ${v.live}`],['',`激奏技能 Lv.${v.gekisou}/5`,`激 ${v.gekisou}`]]:[[growthIcons.supportLevel,`留影等级 Lv.${v.level}`,`Lv.${v.level}`],[growthIcons.rank,`支援 Rank ${v.rank}/5`,`${v.rank}/5`]];return `<span class="growth-row">${stats.map(([url,title,value])=>`<span class="growth-metric" title="${title} · 养成演示值" aria-label="${title}">${url?`<img src="${url}" alt="">`:''}<b>${value}</b></span>`).join('')}</span>`;}
function bandBadge(card){const bandId={'MyGO!!!!!':1,'Ave Mujica':2,'梦限大MewType':3,'millsage':4,'一家Dumb Rock!':5}[card.band];return bandId?`<span class="band-emblem" title="乐队：${esc(card.band)}"><img src="/assets/bands/band-${bandId}.png" alt="${esc(card.band)}乐队"></span>`:'';}
function skillTrigger(kind,index,t){const v=t?growthValues(t,kind,index):null;return `data-skill-card="${(kind==='member'?members:supports)[index].id}" data-skill-leader="${t?(t.slots[t.leader].member===index?'active':'inactive'):'reference'}" data-skill-live="${v?.live||''}" data-skill-gekisou="${v?.gekisou||''}" tabindex="0"`;}

function growthOverlay(t,kind,index){const v=growthValues(t,kind,index),m=(kind==='member'?members:supports)[index];return `${missionMatch(m)}<span class="art-level" title="等级 ${v.level} · 演示值">Lv.${v.level}</span><span class="art-training" title="特训 Rank ${v.rank}/5 · 演示值">训${v.rank}</span><span class="art-band">${bandBadge(m)}</span>${kind==='member'?`<span class="art-awakening" role="img" aria-label="觉醒 ${v.awake}/4" title="觉醒 ${v.awake}/4 · 点亮表示已觉醒，灰显表示未觉醒">${[1,2,3,4].map(n=>`<img src="${growthIcons.rank}" alt="" class="${n<=v.awake?'is-lit':'is-unlit'}">`).join('')}</span><span class="art-skills"><span title="演出技能 ${skillLabel(m.skill)} Lv.${v.live}">演${v.live}</span><span class="gekisou-${m.gekisou}" title="激奏 ${m.gekisou?skillLabel(m.gekisou):'无'} Lv.${v.gekisou}">${m.gekisou?skillLabel(m.gekisou):'无激奏'}${m.gekisou?` ${v.gekisou}`:''}</span></span>`:`<span class="art-skills support-skills"><span class="gekisou-${m.gekisou}" title="激奏类型：${m.gekisou?skillLabel(m.gekisou):'无激奏'}">${m.gekisou?skillLabel(m.gekisou):'无激奏'}</span></span>`}`;}
function pairingMatches(m,u){const symbol=(url,alt)=>`<span class="match-symbol" aria-hidden="true"><img src="${url}" alt=""><img src="${url}" alt=""></span>`;const bandId={'MyGO!!!!!':1,'Ave Mujica':2,'梦限大MewType':3,'millsage':4,'一家Dumb Rock!':5}[m.band];return `<span class="pair-matches">${m.attr===u.attr?`<span class="pair-match match-attribute" title="成员与留影属性相同：${m.attr}">${symbol(m.attributeIcon)}<span>同属性</span></span>`:''}${m.band&&m.band===u.band?`<span class="pair-match match-band" title="成员与留影乐队相同：${m.band}">${symbol(`/assets/bands/band-${bandId}.png`)}<span>同乐队</span></span>`:''}</span>`;}
const crownIcon='<svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m3 6 4 3 3-5 3 5 4-3-2 9H5L3 6Z" fill="currentColor" opacity=".18"/><path d="m3 6 4 3 3-5 3 5 4-3-2 9H5L3 6Zm3 11h8" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/></svg>';
function leaderSummary(t){
 const m=members[t.slots[t.leader].member],skill=cardSkills[m.id]?.find(x=>x.slot==='leader'),level=skill?.levels.at(-1);if(!level)return '';
 const raw=level.effect.replace(/\s+/g,' ').trim(),parts=raw.split(/(?:，)?\s*并且\s*/).map(text=>text.trim().match(/^(.+?)提升([\d.]+)%$/));
 const effect=parts.every(Boolean)?parts.map(([,target,value])=>`${esc(target.trim())} <strong>+${esc(value)}%</strong>`).join('；') :esc(raw);
 return `<section class="leader-effect" aria-label="当前队长技能效果"><span class="leader-simple-name">队长技 · ${esc(m.name)}</span><span class="leader-simple-effect" title="${esc(skill.name)}">${effect}</span><small class="leader-simple-reference">Lv.${level.level} · 最高级参考</small></section>`;
}

function activeMissions(){return s.mode==='gekisou'&&song()&&(s.task==='score'&&s.view==='single'||s.task==='team'&&s.objective!=='power')?songMissions[s.song]||[]:[];}
function missionSummary(){const missions=activeMissions();return missions.length?`<div class="mission-strip" aria-label="当前歌曲三段激奏类型"><strong>♫ ${esc(song().name)}</strong><small>激奏目标</small><span>${missions.map(m=>`<i>${m.index}段 ${m.label}</i>`).join('')}</span></div>`:'';}
function missionMatch(card){const matched=activeMissions().filter(m=>m.type===card.gekisou);return matched.length?`<span class="art-mission-match" title="激奏类型 ${skillLabel(card.gekisou)} 与歌曲第 ${matched.map(m=>m.index).join('、')} 段一致；实际触发取决于技能条件。" aria-label="${skillLabel(card.gekisou)} 匹配歌曲第 ${matched.map(m=>m.index).join('、')} 段"><b>✓ ${skillLabel(card.gekisou)}</b><small>${matched.length===3?'全3段':matched.map(m=>m.index+'段').join('·')}</small></span>`:'';}

function richPair(t,p,i){const m=members[p.member],u=supports[p.support];return `<span class="pair-head"><small>位置 ${i+1}</small>${t.leader===i?'<b class="leader-badge">队长</b>':''}</span><span class="member-art" ${skillTrigger('member',p.member,t)}><img src="${m.image}" alt="${m.card}" loading="lazy"><span class="art-facets"><img src="${m.rarityIcon}" alt="${m.rarity}"><img src="${m.attributeIcon}" alt="${m.attr}"></span>${growthOverlay(t,'member',p.member)}</span><span class="pair-card-name">${m.card}<span class="pair-character"> · ${m.name}</span></span>${pairingMatches(m,u)}<span class="support-block"><span class="support-art" ${skillTrigger('support',p.support,t)}><img src="${u.image}" alt="${u.support}" loading="lazy"><span class="art-facets"><img src="${u.rarityIcon}" alt="${u.rarity}"><img src="${u.attributeIcon}" alt="${u.attr}"></span>${growthOverlay(t,'support',p.support)}</span><span class="support-caption"><strong>${u.support}</strong></span></span>`;}

function conditionItems(){const list=[];const add=(label,title,copy)=>list.push({label,title,copy});add(s.region==='jp'?'日服':'港澳台','服务器',`当前服务器：${s.region==='jp'?'日本':'港澳台'}。目录和卡库按区服区分。`);if(s.task==='event'&&s.eventView==='quick'){add(`道具 +${s.badgeBonus}%`,'道具加成',`游戏显示的道具加成：${s.badgeBonus}%。只影响对应道具奖励。`);add(`pt +${s.pointBonus}%`,'活动 pt 加成',`活动 pt 加成：${s.pointBonus}%。与道具加成分别计算。`);add(s.rank,'稳定评分',`普通演出稳定评分：${s.rank}。`);add(`${s.boost}火/次`,'每次耗火',`每次普通演出使用 ${s.boost} 火。`);add('挑战pt单列','挑战 pt','挑战 pt 不与活动 pt 合并。');return list;}
 const fixed=s.task==='score'?fixedTeam():s.current;const scope=s.task==='score'?'固定队伍':s.pool==='owned'?'我的卡库':'全部卡牌';add(scope,'卡片范围',s.task==='score'?`固定队伍：${fixed?.label||'尚未选择'}。不会重新搜索其他编成。`:s.pool==='owned'?'只在示例持有卡库中推荐。原型没有接真实账号。':'在全部公开卡牌中按参考养成比较。');const growth=s.task==='score'?sourceLabel(fixed):s.pool==='reference'?'满养成参考':s.growth==='train'?'允许培养':'实际养成';add(growth,'养成依据',`${growth}。原型的养成数字为演示值，不写入个人卡库。`);if(s.task!=='score'&&s.pool==='owned'){add(s.growth==='train'?`培养≤${s.trainingLimit}`:'不培养','培养范围',s.growth==='train'?`最多培养 ${s.trainingLimit} 张卡片后比较。`:'保持记录的养成进度。');add(s.trial==='none'?'不试用':s.trial==='member'?'试用成员':s.trial==='support'?'试用留影':'试用两类','临时试用',s.trial==='none'?'不加入未拥有卡牌。':'允许本次比较使用未拥有的卡片，不改变持有记录。');}
 if(s.task==='team'){add({average:'平均分',minimum:'最低分',maximum:'最高分',power:'综合力'}[s.objective],'推荐目标','平均、最低和最高分别比较技能顺序的样例估分；综合力目标不需要歌曲。');}
 if(needsSong()){add(song()?song().name:'未选歌','歌曲',song()?`已选歌曲：${song().name}，${song().band}。`:'请选择一张歌曲谱面。');add(s.difficulty.toUpperCase(),'谱面难度',song()?`${s.difficulty.toUpperCase()} · Lv.${songLevel(song(),s.difficulty)}`:'尚未选曲目，当前难度为 '+s.difficulty.toUpperCase());}
 if(s.task==='score'&&s.view==='songs'){add(s.difficulty.toUpperCase(),'谱面范围',`按 ${s.difficulty.toUpperCase()} 谱面比较歌曲。`);add(s.maxLevel==='40'?'等级不限':`≤${s.maxLevel}级`,'谱面等级上限',`等级上限：${s.maxLevel==='40'?'不限':s.maxLevel}。`);add('AP','判定假设','所有判定均为 Perfect。');add('满LIFE','生命值假设','使用满生命值条件估分。');add('无辅助','辅助假设','未使用辅助效果。');add({average:'按均分',minimum:'按低分',maximum:'按高分'}[s.basis],'判档依据','对已生成的歌曲结果采用对应估分判档，不重新搜索编成。');add({grade:'档位优先',short:'短歌优先',score:'分数优先'}[s.sort],'结果排序','排序只调整已有结果的显示顺序。');}
 else if(s.task==='team'&&s.objective!=='power'||s.task==='score'){add(s.mode==='ordinary'?'普通':'激奏','演出模式',s.mode==='ordinary'?'普通自由演出。':'激奏演出；三段名次 '+s.precision.places.join(' / '));add({perfect:'AP',steady:'参考发挥',practice:'练习发挥',custom:'自定义发挥'}[s.performance],'发挥假设',`当前选择：${{perfect:'全 Perfect',steady:'参考发挥',practice:'练习发挥',custom:'自定义发挥'}[s.performance]}。${precisionSummary(s.precision)}。`);add(`${s.precision.perfect}%P`,'Perfect 比例',`判定中的 Perfect 比例：${s.precision.perfect}%，仅为原型假设。`);add(`LIFE ${s.precision.life}%`,'技能触发时 LIFE',`技能触发时采用 ${s.precision.life}% LIFE。`);add(s.precision.assist?'有辅助':'无辅助','判定辅助',s.precision.assist?'本次启用判定辅助假设。':'本次不启用判定辅助。');if(s.mode==='gekisou')add('名次 '+s.precision.places.join('/'),'激奏三段名次','三段名次示例：'+s.precision.places.join(' / '));}
 if(s.task==='event'){add({badges:'优先道具',points:'优先pt',both:'分别比较'}[s.eventGoal],'刷取目标','道具与活动 pt 分别比较，不合并成一个指标。');add(`${s.budget}火`,'耗火预算',`本次总耗火预算：${s.budget} 火。`);add(s.phase==='cycle'?'普通＋挑战':'仅普通','计算范围',s.phase==='cycle'?'计算普通演出和后续挑战两个阶段，编成应独立确认。':'仅计算普通演出。');add(s.maxLevel==='40'?'等级不限':`≤${s.maxLevel}级`,'稳定完成等级',`稳定完成等级上限：${s.maxLevel==='40'?'不限':s.maxLevel}。`);add(`已有CP ${s.startingCP}`,'已有挑战 pt',`当前已有挑战 pt：${s.startingCP}。`);add(`${s.boost}火/次`,'每次耗火',`普通演出每次使用 ${s.boost} 火。`);add(s.eventContext.name,'活动条件',`${s.eventContext.band} · ${s.eventContext.attribute} · 挑战曲 ${songs.find(x=>x.id===s.eventContext.challengeSong)?.name}，活动样例。`);}
 if(s.task!=='score')add(s.locks.length?`固定${s.locks.length}组`:'无固定配对','编成约束',s.locks.length?`固定位置 ${s.locks.map(i=>i+1).join('、')} 的成员／留影配对。`:'没有固定成员／留影配对。');if(fixed)add(`队长·${members[fixed.slots[fixed.leader].member].short}`,'所选队伍队长',`${fixed.label} 的队长是 ${members[fixed.slots[fixed.leader].member].name}。推荐结果可能另选队长。`);add(`TGW ${s.bonuses.tgw}`,'账号加成',bonusSummary(s.bonuses)+'。本次工具设置，仅演示交互。');add(`乐器 ${s.bonuses.instruments.filter(x=>x>0).length}队`,'乐器养成',s.bonuses.instruments.map((v,i)=>`${demoBands[i]} Lv.${v}`).join('；'));add('评级 '+s.bonuses.ranks.join('/'),'角色评级','当前五个位置的角色评级示例：'+s.bonuses.ranks.join(' / '));return list;}
function filterChips(scope,key,label,rows,value){return `<div class="facet-row"><span>${label}</span><div role="group" aria-label="${label}筛选">${rows.map(([v,text,url,color])=>btn(`${url?`<img src="${url}" alt="">`:color?`<i style="background:${color}"></i>`:''}<span>${text}</span>`,'facet','facet-chip',`data-scope="${scope}" data-key="${key}" data-value="${esc(v)}" aria-label="${esc(text)}" title="${esc(label)}：${esc(text)}" aria-pressed="${v===value}"`)).join('')}</div></div>`;}
function attributeOptions(){return [['all','全部'],...['红赤','绀碧','翡翠','山吹','紫苑'].map(a=>{const c=members.find(m=>m.attr===a);return [a,a,c.attributeIcon,c.color];})];}
function bandOptions(collection){return [['all','全部乐队'],...[...new Set(collection.map(c=>c.band))].map(b=>[b,b])];}
function clearSearch(scope,value,label){return `<label class="search-field"><span>⌕</span><input data-${scope}-query type="search" value="${esc(value)}" placeholder="${label}" aria-label="${label}">${btn('×','clear-query','input-clear',`data-scope="${scope}" aria-label="清空搜索" ${value?'':'hidden'}`)}</label>`;}
