function skillLabel(value){return {simple:'得分提升',life:'LIFE加成',judgement:'判定辅助',score:'得分提升',heal:'生命恢复',judge:'判定辅助','score,heal':'得分＋恢复',combo:'COMBO',just:'JUST',luck:'LUCK'}[value]||'其他';}
