let conditionHelpTrigger=null;
function closeConditionHelp(){const help=document.querySelector('#condition-help');if(help?.matches(':popover-open'))help.hidePopover();if(help?.parentElement!==document.body)document.body.append(help);conditionHelpTrigger?.removeAttribute('aria-describedby');conditionHelpTrigger=null;}
function showConditionHelp(trigger){closeConditionHelp();conditionHelpTrigger=trigger;const help=document.querySelector('#condition-help');(trigger.closest('dialog')||document.body).append(help);help.innerHTML=`<strong>${esc(trigger.dataset.title)}</strong><p>${esc(trigger.dataset.copy)}</p>`;help.style.width=`${Math.min(280,innerWidth-28)}px`;const r=trigger.getBoundingClientRect();help.style.left=`${Math.max(14,Math.min(r.left,innerWidth-Math.min(280,innerWidth-28)-14))}px`;help.style.top=`${r.bottom+135>innerHeight?Math.max(14,r.top-120):r.bottom+6}px`;help.showPopover();trigger.setAttribute('aria-describedby','condition-help');}
document.addEventListener('pointerover',e=>{const tag=e.target.closest('.condition-tag');if(e.pointerType!=='touch'&&tag&&conditionHelpTrigger!==tag)showConditionHelp(tag);});
document.addEventListener('pointerout',e=>{const tag=e.target.closest('.condition-tag');if(tag&&!tag.contains(e.relatedTarget))closeConditionHelp();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&conditionHelpTrigger)closeConditionHelp();});
document.addEventListener('scroll',closeConditionHelp,true);
document.addEventListener('toggle',e=>{if(e.target.matches?.('.card-skill-filters'))cardSkillsOpen=e.target.open;},true);

let skillHelpTrigger=null;
function closeSkillHelp(){const help=document.querySelector('#skill-help');if(help?.matches(':popover-open'))help.hidePopover();if(help&&help.parentElement!==document.body)document.body.append(help);skillHelpTrigger?.removeAttribute('aria-describedby');skillHelpTrigger=null;}
function showSkillHelp(trigger){
 closeSkillHelp();closeConditionHelp();
 const card=[...members,...supports].find(c=>c.id===trigger.dataset.skillCard),skills=cardSkills[card?.id]||[];
 if(!card||!skills.length)return;
 skillHelpTrigger=trigger;const help=document.querySelector('#skill-help');(trigger.closest('dialog')||document.body).append(help);
 const sections=skills.map(skill=>{
  const requested=skill.slot==='live'?Number(trigger.dataset.skillLive):skill.slot==='gekisou'?Number(trigger.dataset.skillGekisou):0;
  const level=skill.levels.find(l=>l.level===requested)||skill.levels.at(-1);
  const label=skill.slot==='leader'?`队长技能${trigger.dataset.skillLeader==='active'?' · 当前生效':trigger.dataset.skillLeader==='inactive'?' · 未任队长':' · 参考'}`:skill.slot==='live'?'演出技能':skill.slot==='gekisou'?'激奏技能':skill.slot.startsWith('gekisou')?'激奏支援':'支援技能';
  return `<section class="skill-help-section"><div><b>${label}</b><small>Lv.${level.level}${requested?' · 演示养成':' · 最高级参考'}</small></div><h4>${esc(skill.name)}</h4><p>${esc(level.effect)}</p></section>`;
 }).join('');
 help.innerHTML=`<div class="skill-help-header">${bandBadge(card)}<div><strong>${esc(card.card)}</strong><small>${esc(card.name)} · ${esc(card.band)}</small></div></div>${sections}<p class="skill-help-note">技能效果来自公开目录；养成进度为原型演示。</p>`;
 help.style.width=`${Math.min(320,innerWidth-24)}px`;help.showPopover();
 const r=trigger.getBoundingClientRect(),h=help.getBoundingClientRect(),gap=10;
 let left=r.right+gap;if(left+h.width>innerWidth-12)left=r.left-h.width-gap;
 if(left<12)left=Math.max(12,Math.min(r.left,innerWidth-h.width-12));
 const top=Math.max(12,Math.min(r.top,innerHeight-h.height-12));
 help.style.left=`${left}px`;help.style.top=`${top}px`;trigger.setAttribute('aria-describedby','skill-help');
}
document.addEventListener('pointerover',e=>{const card=e.target.closest('[data-skill-card]');if(e.pointerType!=='touch'&&card&&skillHelpTrigger!==card)showSkillHelp(card);});
document.addEventListener('pointerout',e=>{const card=e.target.closest('[data-skill-card]');if(card&&!card.contains(e.relatedTarget))closeSkillHelp();});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-skill-card]'))showSkillHelp(e.target);});
document.addEventListener('focusout',e=>{if(e.target===skillHelpTrigger)closeSkillHelp();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSkillHelp();});
document.addEventListener('scroll',closeSkillHelp,true);
document.addEventListener('close',closeSkillHelp,true);
window.addEventListener('resize',closeSkillHelp);

