function dismissDialog(d){if(!d?.open)return;const returnPicker=d.id==='library'&&d.classList.contains('is-editor')&&editorOrigin==='picker';d.close();stopSimulation();closeSelect();closeSkillHelp();closeConditionHelp();hideToast();if(returnPicker){renderTeamPicker();open('team-picker');}}
document.addEventListener('click',e=>{const control=e.target.closest?.('[data-action="close-dialog"]');if(!control)return;e.preventDefault();e.stopImmediatePropagation();dismissDialog(control.closest('dialog'));},true);

let backdropStart=null;
function outsideDialog(e,d){if(e.target!==d)return false;const r=d.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom;}
document.addEventListener('pointerdown',e=>{backdropStart=e.target.matches?.('dialog[open]')&&outsideDialog(e,e.target)?e.target:null;});
document.addEventListener('click',e=>{if(backdropStart&&outsideDialog(e,backdropStart))dismissDialog(backdropStart);backdropStart=null;});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('cancel',e=>{e.preventDefault();dismissDialog(d);}));
function getSetting(key,index){const [group,property]=key.split('.');const v=settingsDraft[group][property];return index==null||index===''?v:v[Number(index)];}
function setSetting(key,index,value){const [group,property]=key.split('.');if(index==null||index==='')settingsDraft[group][property]=value;else settingsDraft[group][property][Number(index)]=value;}
function settingControl(key,label,min,max,index='',presets=[]){const v=getSetting(key,index);return `<div class="setting-control"><div class="setting-stepper">${btn('−','settings-step','',`data-key="${key}" data-index="${index}" data-step="-1" data-min="${min}" data-max="${max}" aria-label="减少${label}"`)}<input type="number" min="${min}" max="${max}" value="${v}" data-setting="${key}" data-index="${index}" aria-label="${label}">${btn('＋','settings-step','',`data-key="${key}" data-index="${index}" data-step="1" data-min="${min}" data-max="${max}" aria-label="增加${label}"`)}</div>${presets.length?`<div class="setting-presets">${presets.map(n=>btn(n,'settings-preset','',`data-key="${key}" data-index="${index}" data-value="${n}" aria-label="${label}设为${n}" aria-pressed="${v===n}"`)).join('')}</div>`:''}</div>`;}
function settingsRange(key,label,unit='',index=''){return `<label class="setting-range"><span>${label}<output>${getSetting(key,index)}${unit}</output></span><input type="range" min="0" max="100" step="1" value="${getSetting(key,index)}" data-setting="${key}" data-index="${index}" aria-label="${label}"><small><span>0${unit}</span><span>100${unit}</span></small></label>`;}
function openSettings(page){settingsPage=page;settingsDraft={bonuses:structuredClone(s.bonuses),precision:structuredClone(s.precision),eventContext:structuredClone(s.eventContext)};renderSettings();open('settings');}
function renderSettings(){closeSelect();const d=document.querySelector('#settings');const scroll=d.querySelector('.settings-body')?.scrollTop||0;const team=s.current||fixedTeam()||savedTeams()[0];const b=settingsDraft.bonuses,p=settingsDraft.precision,c=settingsDraft.eventContext;
 const focused=document.activeElement?.closest('#settings')?document.activeElement:null;const focusedData=focused?{...focused.dataset}:null;const focusedValue=focused?.type==='radio'?focused.value:null;const tabs=settingsPage==='event'?[['event','活动与挑战']]:s.task==='event'||s.task==='team'&&s.objective==='power'||s.task==='score'&&s.view==='songs'?[['bonuses','账号加成']]:[['bonuses','账号加成'],['performance','精细发挥']];
 let body='';
 if(settingsPage==='bonuses')body=`<div class="bonus-preset-bar"><p class="settings-intro">本次计算采用的账号养成，应用后更新条件摘要。</p>${btn('一键满级','max-bonuses','secondary')}</div><div class="bonus-columns"><section><header><h3>乐器 / 乐队道具</h3>${btn('全部满级','max-bonus-group','quiet','data-group="instruments" aria-label="乐器全部满级"')}</header>${demoBands.map((band,i)=>`<div class="bonus-row"><span class="bonus-label"><img src="/assets/bands/band-${i+1}.png" alt=""><span>${band}</span></span>${settingControl('bonuses.instruments',band+'乐器等级',0,30,i,[0,10,20,30])}</div>`).join('')}</section><section><header><h3>角色评级</h3>${btn('全部满级','max-bonus-group','quiet','data-group="ranks" aria-label="角色评级全部满级"')}</header>${team.slots.map((slot,i)=>`<div class="bonus-row"><span class="bonus-label"><span class="position-number">${i+1}</span>${members[slot.member].name}</span>${settingControl('bonuses.ranks',members[slot.member].name+'角色评级',1,50,i,[1,10,30,50])}</div>`).join('')}</section></div>${tgwOptions(b.tgw)}`;
 if(settingsPage==='performance')body=`<p class="settings-intro">先选接近自己的预设，再调整判定与 LIFE。三段名次在激奏模式下显示。</p><div class="performance-presets" role="group" aria-label="发挥预设">${[['perfect','全 Perfect','100% · 满 LIFE'],['steady','稳定发挥','97% · 满 LIFE'],['practice','练习发挥','90% · 70% LIFE']].map(([v,label,copy])=>btn(`<strong>${label}</strong><small>${copy}</small>`,'performance-preset','',`data-preset="${v}" aria-pressed="${p.perfect==={perfect:100,steady:97,practice:90}[v]&&p.life===(v==='practice'?70:100)}"`)).join('')}</div><div class="performance-ranges">${settingsRange('precision.perfect','Perfect 比例','%')}${settingsRange('precision.life','技能触发时 LIFE','%')}</div><label class="settings-toggle"><span><strong>判定辅助</strong><small>开启后在条件摘要中标明</small></span><input type="checkbox" role="switch" data-setting="precision.assist" aria-label="判定辅助" ${p.assist?'checked':''}></label>${s.mode==='gekisou'?`<section class="placement-settings"><h3>激奏三段名次</h3><div>${[0,1,2].map(i=>`<span>第 ${i+1} 段${settingControl('precision.places',`第${i+1}段名次`,1,5,i,[1,2,3])}</span>`).join('')}</div></section>`:''}<div class="precision-preview"><span>当前假设</span><strong>${precisionSummary(p)}</strong><small>原型以比例演示精细判定；计算结果仍为样例。</small></div>`;
 if(settingsPage==='event')body=`<p class="settings-intro">先选择活动条件，再确认独立的挑战曲和编成。均为演示场景。</p><section class="event-samples"><h3>活动样例</h3><div>${demoBands.slice(0,3).map((band,i)=>btn(`<img src="/assets/bands/band-${i+1}.png" alt=""><span><strong>${band}</strong><small>示例活动</small></span>`,'settings-event','',`data-name="${band} · 示例活动" data-band="${band}" aria-pressed="${c.band===band}"`)).join('')}</div></section><section class="event-attribute"><h3>活动属性</h3><div class="setting-presets">${attributeOptions().slice(1).map(([v,l,url])=>`<label><input type="radio" name="event-attribute" data-setting="eventContext.attribute" value="${v}" ${c.attribute===v?'checked':''}><img src="${url}" alt="">${l}</label>`).join('')}</div></section><label class="challenge-song-field"><span>挑战曲</span><select data-setting="eventContext.challengeSong" aria-label="挑战曲">${songs.map(x=>`<option value="${x.id}" ${x.id===c.challengeSong?'selected':''}>${x.name} · ${x.band}</option>`).join('')}</select></label><section class="challenge-team-settings"><h3>挑战专用编成</h3><div class="setting-presets">${savedTeams().map(t=>btn(t.label,'settings-team','',`data-team="${t.id}" aria-pressed="${t.id===c.challengeTeam}"`)).join('')}</div>${roster(savedTeams().find(t=>t.id===c.challengeTeam)||savedTeams()[0])}</section>`;
 d.innerHTML=dialogHeader(settingsPage==='event'?'活动与挑战设置':'加成与发挥','settings-title')+`<nav class="settings-tabs" aria-label="设置分类">${tabs.map(([v,label])=>btn(label,'settings-tab','',`data-page="${v}" aria-pressed="${settingsPage===v}"`)).join('')}</nav><div class="settings-body">${body}</div><footer class="selection-footer"><span>仅用于本次原型<small>关闭或取消会舍弃未应用的修改</small></span><div>${btn('取消','close-dialog','secondary')}${btn('应用设置','save-settings','primary')}</div></footer>`;d.querySelector('.settings-body').scrollTop=scroll;if(focusedData){[...d.querySelectorAll('button,input,select')].find(el=>Object.entries(focusedData).every(([k,v])=>el.dataset[k]===v)&&(focusedValue===null||el.value===focusedValue))?.focus({preventScroll:true});}
}
function saveSettings(){if(settingsPage==='event')change('eventContext',structuredClone(settingsDraft.eventContext));else{change('bonuses',structuredClone(settingsDraft.bonuses));change('precision',structuredClone(settingsDraft.precision));s.performance=s.precision.perfect===100&&s.precision.life===100&&!s.precision.assist?'perfect':'custom';}document.querySelector('#settings').close();render();notify('设置已应用，计算条件已更新。');}
document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.setting)return;if(['radio','checkbox'].includes(el.type))return;const value=el.type==='number'||el.type==='range'?Math.max(Number(el.min),Math.min(Number(el.max),Number(el.value)||0)):el.value;setSetting(el.dataset.setting,el.dataset.index,value);if(el.type==='range'){el.closest('label').querySelector('output').textContent=value+'%';document.querySelector('.precision-preview strong').textContent=precisionSummary(settingsDraft.precision);}});
document.addEventListener('change',e=>{const el=e.target;if(!el.dataset.setting)return;if(el.type==='checkbox')setSetting(el.dataset.setting,'',el.checked);else if(el.type==='radio')setSetting(el.dataset.setting,'',el.value);renderSettings();});
function demoCandidate(label,index){const t={...fixtureTeam(label),leader:index===0?2:0,slots:index===0?defaultSlots():defaultSlots().map((p,j)=>({...p,support:(j+1)%5})),score:(s.objective==='power'?284000:1080000)-index*18000};if(s.current){for(const i of s.locks)t.slots[i]=structuredClone(s.current.slots[i]);for(const kind of ['member','support']){const used=new Set(s.locks.map(i=>t.slots[i][kind]));for(let i=0;i<5;i++)if(!s.locks.includes(i)){if(used.has(t.slots[i][kind]))t.slots[i][kind]=[...Array((kind==='member'?members:supports).length).keys()].find(n=>!used.has(n));used.add(t.slots[i][kind]);}}}return t;}
function pairCounts(t){return {band:t.slots.filter(p=>members[p.member].band===supports[p.support].band).length,attribute:t.slots.filter(p=>members[p.member].attr===supports[p.support].attr).length};}
function reasonPreview(t,r){const c=pairCounts(t);return `<div class="reason-preview"><span><strong>配对依据</strong><small>${c.attribute}/5 同属性 · ${c.band}/5 同乐队${r.locks.length?' · '+r.locks.length+' 组固定':''}</small></span>${btn('查看原因','open-reasons','quiet')}</div>`;}
function openReasons(){const r=result(),t=chosen(),c=pairCounts(t);const x=songs.find(x=>x.id===r.songId);const missions=songMissions[r.songId]||[];
 open('insight',dialogHeader('推荐原因','insight-title',`${t.label} · ${r.songName} · 编成快照`)+`<div class="insight-body"><div class="insight-overview"><div><strong>${c.attribute}<small>/5</small></strong><span>同属性配对</span></div><div><strong>${c.band}<small>/5</small></strong><span>同乐队配对</span></div><div><strong>${r.locks.length}<small>组</small></strong><span>固定配对</span></div></div><p class="insight-caption">先看搭配条件，再查看每组的技能。以下解释当前样例的组成，不代表搜索最优性。</p><div class="pair-reasons">${t.slots.map((p,i)=>{const m=members[p.member],u=supports[p.support];const live=cardSkills[m.id]?.find(v=>v.slot==='live');return `<details ${i===0?'open':''}><summary><span class="reason-position">${i+1}</span><span class="reason-member">${m.name}${i===t.leader?' · 队长':''}<small>${m.card}</small></span><span class="reason-pair-tags">${m.attr===u.attr?'<b>同属性</b>':''}${m.band===u.band?'<b>同乐队</b>':''}${r.locks.includes(i)?'<b>固定</b>':''}</span><span>⌄</span></summary><div class="pair-reason-content"><p><span>成员 / 留影</span><strong>${m.card} ＋ ${u.card}</strong></p><p><span>搭配条件</span>${m.attr===u.attr?`属性一致：${m.attr}`:'属性不同'} · ${m.band===u.band?`乐队一致：${m.band}`:'乐队不同'}${x?` · 歌曲属性${m.attr===x.attribute?'一致':'不同'}`:''}</p><p><span>演出技能</span>${live?esc(live.levels.at(-1).effect):skillLabel(m.skill)} <small>最高级参考</small></p>${r.mode==='gekisou'?`<p><span>激奏类型</span>${skillLabel(m.gekisou)} · ${missions.some(v=>v.type===m.gekisou)?'对应歌曲任务类型':'未对应歌曲任务类型'}</p>`:''}</div></details>`;}).join('')}</div><section class="reason-scope"><h3>本次比较范围</h3><dl><div><dt>卡片范围</dt><dd>${r.source==='reference'?'全部卡牌参考':'示例持有卡库'}</dd></div><div><dt>养成</dt><dd>${sourceLabel(t)}</dd></div><div><dt>账号条件</dt><dd>${bonusSummary(r.bonuses)}</dd></div><div><dt>发挥</dt><dd>${precisionSummary(r.precision,r.mode)}</dd></div></dl>${leaderSummary(t)}</section></div><footer class="selection-footer"><span>切换推荐方案后，可分别查看组成原因</span>${btn('关闭','close-dialog','secondary')}</footer>`);
}
function openBreakdown(){detailOrder='average';renderBreakdown();open('insight');}
function renderBreakdown(){stopSimulation();const r=result(),t=r.team,x=songs.find(v=>v.id===r.songId),duration=x?.time||120;const order=detailOrder==='minimum'?[4,0,3,1,2]:detailOrder==='maximum'?[2,1,3,0,4]:[0,1,2,3,4];const values=[18,21,23,20,18];const total=detailOrder==='minimum'?990000:detailOrder==='maximum'?1160000:1080000;
 document.querySelector('#insight').innerHTML=dialogHeader('技能顺序与计分明细','insight-title',`${r.songName} · ${r.difficulty.toUpperCase()} · 示意数据`)+`<div class="insight-body"><div class="breakdown-heading"><div><span>${{average:'平均',minimum:'最低',maximum:'最高'}[detailOrder]}分示例</span><strong>${fmt(total)}</strong></div><div class="setting-presets" role="group" aria-label="技能顺序">${[['average','参考顺序'],['minimum','较低顺序'],['maximum','较高顺序']].map(([v,l])=>btn(l,'detail-order','',`data-order="${v}" aria-pressed="${v===detailOrder}"`)).join('')}</div></div><section class="skill-timeline"><header><h3>技能触发顺序</h3><small>0:00 — ${Math.floor(duration/60)}:${String(duration%60).padStart(2,'0')}</small></header><div>${order.map((i,n)=>`<span><b>${n+1}</b><strong>${members[t.slots[i].member].short}</strong><small>${Math.round(duration*(n+1)/6)}s</small></span>`).join('')}</div></section><section class="contribution-list"><header><h3>位置贡献</h3><small>占比仅演示明细样式</small></header>${t.slots.map((p,i)=>`<div><span>${members[p.member].name}${i===t.leader?' · 队长':''}</span><i style="--contribution:${values[i]}%"></i><strong>${values[i]}%</strong></div>`).join('')}</section><dl class="score-components"><div><dt>基础与综合力部分</dt><dd>${fmt(Math.round(total*.72))}</dd></div><div><dt>演出技能部分</dt><dd>${fmt(Math.round(total*.28))}</dd></div><div><dt>合计</dt><dd>${fmt(total)}</dd></div></dl><p class="insight-caption">真实计算接入后替换触发时间、覆盖率和贡献值。本次使用编成与条件快照展示查看流程。</p></div><footer class="selection-footer"><span>${precisionSummary(r.precision,r.mode)}</span>${btn('关闭','close-dialog','secondary')}</footer>`;
}
function openPlanDetail(){const r=result(),c=r.eventContext;open('insight',dialogHeader('阶段规划','insight-title',c.name)+`<div class="insight-body"><div class="plan-flow"><section><small>普通演出</small><h3>${Math.floor(r.budget/Number(r.boost))} 次 · ${r.budget} 火预算</h3><p>参考 SS 评分，普通奖励与挑战 pt 分开记录。</p><strong>${fmt(r.budget*1240)} 徽章</strong></section>${r.phase==='cycle'?`<span>→</span><section><small>后续挑战</small><h3>${songs.find(x=>x.id===c.challengeSong)?.name}</h3><p>使用 ${savedTeams().find(t=>t.id===c.challengeTeam)?.label}</p><strong>已有 ${r.startingCP} pt · 剩余示例 60 pt</strong></section>`:''}</div><p class="insight-caption">次数与奖励为布局样例，活动规则尚未连接真实计算。</p></div><footer class="selection-footer">${btn('关闭','close-dialog','secondary')}</footer>`);}

// V14: independent song entry, actual TGW intervals and in-memory activation playback.
function tgwBonus(rank){return (tgwRanges.find(x=>rank>=x.min&&rank<=x.max)?.bp||0)/100;}
function tgwOptions(rank){return `<section class="tgw-intervals"><header><h3>TGW 能力加成</h3><small>相同加成的等级合并显示</small></header><div role="group" aria-label="TGW 加成等级">${tgwRanges.map(x=>btn(`<span>Lv.${x.min}${x.max>x.min?'–'+x.max:''}</span><strong>${x.bp?'+'+x.bp/100+'%':'无加成'}</strong>`,'settings-preset','tgw-option',`data-key="bonuses.tgw" data-value="${x.min}" aria-label="TGW Lv.${x.min}${x.max>x.min?'至'+x.max:''} ${x.bp?'加成'+x.bp/100+'%':'无加成'}" aria-pressed="${rank>=x.min&&rank<=x.max}"`)).join('')}</div></section>`;}
function songWorkspace(){const x=song();return `<section class="song-workspace" aria-label="独立选曲模块"><div class="song-workspace-heading"><small>本次谱面</small><span>${s.task==='team'?'用于比较推荐编成':'用于这支队伍的单曲估分'}</span></div><button class="song-entry" data-action="open-song">${x?`<img src="${x.cover}" alt="${esc(x.name)}封面">`:'<span class="song-entry-empty" aria-hidden="true">♪</span>'}<span><strong>${x?esc(x.name):'选择歌曲谱面'}</strong><small>${x?`${esc(x.band)} · ${s.difficulty.toUpperCase()} · Lv.${songLevel(x,s.difficulty)}`:'直接选择歌曲和难度'}</small></span><b>${x?'更换谱面':'选择谱面'} ›</b></button>${missionSummary()}</section>`;}
let simulation=null,simulationTimer=null;
function stopSimulation(){clearInterval(simulationTimer);simulationTimer=null;if(simulation)simulation.playing=false;}
function simulationSkill(kind,index,slot,t){const m=(kind==='member'?members:supports)[index],skill=(cardSkills[m.id]||[]).find(x=>x.slot===slot);if(!skill)return null;const g=growthValues(t,kind,index),level=slot==='live'?g.live:slot==='gekisou'?g.gekisou:g.rank;const row=skill.levels.find(v=>v.level===level)||skill.levels.at(-1);return {...skill,level:row.level,effect:row.effect.replace(/\s+/g,' ').trim()};}
function conditionalNumber(effect,pattern,matches){const values=[...effect.matchAll(pattern)].map(m=>Number(m[1]));return values.length?values[matches?values.length-1:0]:0;}
function simulationItems(){const sim=simulation;return sim.team.slots.map((p,i)=>{const m=members[p.member],u=supports[p.support],live=simulationSkill('member',p.member,'live',sim.team),support=simulationSkill('support',p.support,'support_1',sim.team),gekisou=simulationSkill('member',p.member,'gekisou',sim.team),gekisouSupport=simulationSkill('support',p.support,'gekisou_support_1',sim.team);const requiredBand=support?.effect.match(/若为「(.+?)」/)?.[1];const bandMatches=requiredBand?m.band===requiredBand:m.band===u.band;const base=Number(live?.effect.match(/([\d.]+)秒内/)?.[1]||5),extra=conditionalNumber(support?.effect||'',/延长([\d.]+)秒/g,bandMatches),heal=conditionalNumber(support?.effect||'',/LIFE(?:回复|恢复)([\d.]+)/g,bandMatches);return {i,m,u,live,support,gekisou,gekisouSupport,start:sim.duration*(i+1)/6,base,extra,heal,bandMatches};});}
function simulationStages(){const missions=songMissions[simulation.songId]||[];return missions.map((m,i)=>({...m,start:simulation.duration*(.15+i*.27),end:simulation.duration*(.15+i*.27+.14)}));}
function simulationLifeAt(time,items){return Math.min(1000,simulation.life+items.filter(x=>x.start<=time).reduce((sum,x)=>sum+x.heal,0));}
function activationState(item,items){const sim=simulation;if(sim.view==='live'){const before=sim.life+items.filter(x=>x.start<item.start).reduce((sum,x)=>sum+x.heal,0),life=Math.min(1000,before),duration=item.base+item.extra;const active=sim.time>=item.start&&sim.time<item.start+duration,waiting=sim.time<item.start;const threshold=Number(item.live?.effect.match(/LIFE在(\d+)/)?.[1]||0);const values=[...(item.live?.effect||'').matchAll(/得分提升([\d.]+)%/g)].map(v=>Number(v[1]));let rate=values[threshold&&life>=threshold?values.length-1:0]||0;const judgementMet=!/PERFECT以上/.test(item.live?.effect||'')||sim.judgement==='perfect';if(!judgementMet)rate=0;return {active,waiting,done:!waiting&&!active,label:waiting?'等待发动':active?'发动中':'已结束',remaining:Math.max(0,item.start+duration-sim.time),rate,life,threshold,condition:threshold?life>=threshold?`LIFE ${life} ≥ ${threshold} · 强化生效`:`LIFE ${life} < ${threshold} · 使用基础效果`:judgementMet?'当前判定满足技能条件':'当前判定未满足加分条件',memberActive:active, supportActive:active};}
 const stage=simulationStages().find(x=>sim.time>=x.start&&sim.time<x.end),memberTypeMatch=!!stage&&stage.type===item.m.gekisou,supportTypeMatch=!!stage&&stage.type===item.u.gekisou;const comboMinimum=Number(item.gekisou?.effect.match(/COMBO保持在(\d+)/)?.[1]||0),comboMet=!comboMinimum||sim.combo>=comboMinimum;const active=memberTypeMatch&&comboMet||supportTypeMatch;const prior=simulationStages().filter(x=>x.end<=sim.time).length;return {active,waiting:!stage&&prior<3,done:!stage&&prior===3,label:!stage?prior===3?'已结束':'等待段落':active?'发动中':memberTypeMatch&&!comboMet?'条件未满足':'类型不匹配',remaining:stage?stage.end-sim.time:0,rate:0,life:sim.life,threshold:0,condition:!stage?'等待对应激奏段落':memberTypeMatch?comboMet?`第 ${stage.index} 段 ${stage.label} · 类型匹配`:`COMBO ${sim.combo} < ${comboMinimum}`:`第 ${stage.index} 段 ${stage.label} · 成员类型不匹配`,memberActive:memberTypeMatch&&comboMet,supportActive:supportTypeMatch,stage};
}
function simulationTime(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
function openSimulation(){const r=result();if(!r)return;stopSimulation();simulation={team:structuredClone(s.task==='team'?chosen():r.team),songId:r.songId,duration:songs.find(x=>x.id===r.songId)?.time||120,songName:r.songName,difficulty:r.difficulty,view:r.mode==='gekisou'?'gekisou':'live',time:0,speed:4,playing:false,life:(r.precision?.life??100)*10,judgement:'perfect',combo:30};renderSimulation();}
function renderSimulation(){const sim=simulation;if(!sim)return;const items=simulationItems();const stages=simulationStages();const marks=sim.view==='live'?items.map(x=>({start:x.start,end:x.start+x.base+x.extra,label:x.m.short})):stages.map(x=>({start:x.start,end:x.end,label:x.index+'段 '+x.label}));open('insight',dialogHeader('技能发动模拟','insight-title',`${esc(sim.songName)} · ${sim.difficulty.toUpperCase()} · 发动时间为示意`)+`<div class="simulation-body"><div class="simulation-head"><div class="setting-presets" role="group" aria-label="技能模拟类型">${[['live','演出技能'],['gekisou','激奏技能']].map(([v,l])=>btn(l,'simulation-view','',`data-view="${v}" aria-pressed="${sim.view===v}"`)).join('')}</div><span data-simulation-clock>00:00 / ${simulationTime(sim.duration)}</span></div><div class="simulation-controls">${btn('播放','simulation-play','primary','aria-label="播放技能模拟"')}${btn('下一次发动','simulation-next','secondary')}${btn('重置','simulation-reset','quiet')}<div class="setting-presets" role="group" aria-label="播放速度">${[1,2,4].map(v=>btn(v+'×','simulation-speed','',`data-speed="${v}" aria-pressed="${v===sim.speed}"`)).join('')}</div></div><div class="simulation-scrubber"><div class="simulation-markers">${marks.map(x=>`<span style="left:${x.start/sim.duration*100}%" title="${esc(x.label)} · ${simulationTime(x.start)}">${esc(x.label)}</span>`).join('')}</div><input type="range" min="0" max="${sim.duration}" step="0.1" value="${sim.time}" data-simulation-input="time" aria-label="模拟播放进度"></div><div class="simulation-assumptions"><label><span>初始 LIFE</span><input type="range" min="0" max="1000" step="10" value="${sim.life}" data-simulation-input="life" aria-label="模拟初始LIFE"><output data-life-input>${sim.life}</output></label>${sim.view==='live'?`<label><span>当前判定</span><select data-simulation-input="judgement" aria-label="模拟当前判定"><option value="perfect" ${sim.judgement==='perfect'?'selected':''}>PERFECT</option><option value="great" ${sim.judgement==='great'?'selected':''}>GREAT</option><option value="good" ${sim.judgement==='good'?'selected':''}>GOOD</option><option value="miss" ${sim.judgement==='miss'?'selected':''}>MISS</option></select></label>`:`<label><span>激奏 COMBO</span><input type="number" min="0" max="1000" value="${sim.combo}" data-simulation-input="combo" aria-label="模拟激奏COMBO"></label>`}<strong data-simulation-life>LIFE ${sim.life}</strong></div><div class="simulation-detail-grid"><div class="activation-rows">${items.map(x=>`<article data-activation-row="${x.i}"><div class="activation-card"><img src="${x.m.image}" alt="${esc(x.m.card)}"><span><strong>${x.m.name}${x.i===sim.team.leader?' · 队长':''}</strong><small>${sim.view==='live'?x.live?.name||'无演出技能':skillLabel(x.m.gekisou)}</small></span></div><div class="activation-timing"><div class="activation-bar">${sim.view==='live'?`<i style="left:${x.start/sim.duration*100}%;width:${x.base/sim.duration*100}%"></i>${x.extra?`<i class="support-extension" style="left:${(x.start+x.base)/sim.duration*100}%;width:${x.extra/sim.duration*100}%"></i>`:''}`:stages.filter(m=>m.type===x.m.gekisou||m.type===x.u.gekisou).map(m=>`<i style="left:${m.start/sim.duration*100}%;width:${(m.end-m.start)/sim.duration*100}%"></i>`).join('')}<b data-playhead></b></div><small>${sim.view==='live'?`${simulationTime(x.start)} · ${x.base}s${x.extra?' + 留影延长 '+x.extra+'s':''}`:`成员 ${skillLabel(x.m.gekisou)} · 留影 ${skillLabel(x.u.gekisou)}`}</small></div><div class="activation-state"><strong data-activation-label>等待发动</strong><small data-activation-remaining></small></div></article>`).join('')}</div><section class="active-skill-panel" aria-live="off"><header><h3>当前发动情况</h3><small data-active-count>尚未发动</small></header><div data-active-effects></div></section></div></div><footer class="selection-footer"><span>技能效果来自目录；时间与条件变化用于原型演示</span>${btn('关闭模拟','close-dialog','secondary')}</footer>`).classList.add('is-simulation');updateSimulation();}
function updateSimulation(){const sim=simulation,d=document.querySelector('#insight');if(!sim||!d.open||!d.classList.contains('is-simulation'))return;const items=simulationItems(),states=items.map(x=>activationState(x,items));d.querySelector('[data-simulation-clock]').textContent=simulationTime(sim.time)+' / '+simulationTime(sim.duration);d.querySelector('[data-simulation-input="time"]').value=sim.time;const play=d.querySelector('[data-action="simulation-play"]');play.textContent=sim.playing?'暂停':'播放';play.setAttribute('aria-label',sim.playing?'暂停技能模拟':'播放技能模拟');d.querySelector('[data-life-input]').textContent=sim.life;d.querySelector('[data-simulation-life]').textContent='LIFE '+(sim.view==='live'?simulationLifeAt(sim.time,items):sim.life);d.querySelectorAll('[data-action="simulation-speed"]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.speed)===sim.speed));states.forEach((state,i)=>{const row=d.querySelector(`[data-activation-row="${i}"]`);row.classList.toggle('is-active',state.active);row.classList.toggle('is-complete',state.done);row.querySelector('[data-activation-label]').textContent=state.label;row.querySelector('[data-activation-remaining]').textContent=state.active?`剩余 ${state.remaining.toFixed(1)}s`:sim.view==='live'&&state.waiting?simulationTime(items[i].start):'';row.querySelector('[data-playhead]').style.left=sim.time/sim.duration*100+'%';});const active=states.map((state,i)=>({state,item:items[i]})).filter(x=>x.state.active);d.querySelector('[data-active-count]').textContent=active.length?active.length+' 组发动中':'当前无技能发动';d.querySelector('[data-active-effects]').innerHTML=active.map(({state,item})=>`<div class="active-effect-item"><strong>${item.m.name}${sim.view==='live'?state.rate?' · 得分 +'+state.rate+'%':' · 当前判定无加分':''}</strong><p>${state.condition}</p>${state.memberActive?`<small>${esc(sim.view==='live'?item.live?.effect||'':item.gekisou?.effect||'')}</small>`:''}${state.supportActive?`<p class="support-activation"><b>留影 · ${item.u.card}</b><small>${esc(sim.view==='live'?item.support?.effect||'':item.gekisouSupport?.effect||'')}</small></p>`:''}</div>`).join('')||`<p class="simulation-idle">${sim.time>=sim.duration?'播放结束，可以重置或拖动回看。':'播放、拖动进度，或跳到下一次发动。'}<small>${sim.view==='live'?'紫色表示演出技能，金色表示留影延长。':'按歌曲三段类型展示成员和留影是否匹配；COMBO 条件可调整。'}</small></p>`;}
function toggleSimulation(){if(!simulation)return;if(simulation.playing){stopSimulation();updateSimulation();return;}if(simulation.time>=simulation.duration)simulation.time=0;simulation.playing=true;simulationTimer=setInterval(()=>{if(!document.querySelector('#insight').open){stopSimulation();return;}simulation.time=Math.min(simulation.duration,simulation.time+.1*simulation.speed);if(simulation.time>=simulation.duration)stopSimulation();updateSimulation();},100);updateSimulation();}
function resetSimulation(){stopSimulation();if(simulation)simulation.time=0;updateSimulation();}
function nextSimulation(){stopSimulation();if(!simulation)return;const starts=simulation.view==='live'?simulationItems().map(x=>x.start):simulationStages().map(x=>x.start);simulation.time=(starts.find(x=>x>simulation.time+.15)??simulation.duration)+.1;simulation.time=Math.min(simulation.time,simulation.duration);updateSimulation();}
document.addEventListener('input',e=>{const k=e.target.dataset.simulationInput;if(!k||!simulation)return;stopSimulation();simulation[k]=k==='judgement'?e.target.value:Number(e.target.value);updateSimulation();});
document.addEventListener('close',e=>{if(e.target.id==='insight')stopSimulation();},true);

readURL();sync();render();
